Object.assign(window.SB_FEED_BODY, {"pl-strait":{"src":"act:strait","route":"#/atlas/honey/strait","cta":"Open the Wide Strait","title":"Act VI · The Wide Strait","body":"15 stops on this road, from “-eau ending (silent -x plural)” to “Celtic & Gaelic Loanwords”."},"li-u76":{"src":"concept:50:concept","route":"#/stop/u76","cta":"Open this stop","title":"-eau ending (silent -x plural)","body":"French words ending in -eau use the plural -eaux — the x is silent in both forms. The vowel combination e-a-u = /oh/ is a reliable French signal. Four letters make one sound."},"lc-u76-0":{"src":"concept:50:cards:0","route":"#/stop/u76","cta":"Open this stop","title":"-eau ending (silent -x plural) · The -eau Pattern","body":"French -eau = /oh/. Four letters, one syllable, one sound. Tableau (picture/scene), plateau (flat highland), château (castle), bureau (desk/office), trousseau (bride's possessions), gateau (French cake), flambeau (torch). All pronounced with /oh/ at the end."},"lc-u76-1":{"src":"concept:50:cards:1","route":"#/stop/u76","cta":"Open this stop","title":"-eau ending (silent -x plural) · The Silent Plural -eaux","body":"Singular -eau → plural -eaux — the x is completely silent. Both forms pronounced identically: tableau = tableaux = /TAB-loh/. This is a classic spelling bee trap: asked to spell the plural, many write -eaus. It is -eaux. Always. No exceptions."},"lc-u76-2":{"src":"concept:50:cards:2","route":"#/stop/u76","cta":"Open this stop","title":"-eau ending (silent -x plural) · Portmanteau — a Special Word","body":"Portmanteau (porter = carry + manteau = cloak) = a large hinged suitcase. Lewis Carroll also coined portmanteau word for two words merged into one: smog = smoke + fog; brunch = breakfast + lunch; motel = motor + hotel. The suitcase that holds two things becomes the word that holds two words."},"lc-u76-3":{"src":"concept:50:cards:3","route":"#/stop/u76","cta":"Open this stop","title":"-eau ending (silent -x plural) · More -eau Words","body":"Nouveau (new, as in nouveau riche = newly wealthy). Beau (admirer/boyfriend). Rondeau (a type of poem). Morceau (a short musical piece). Rideau (a curtain). Bordeau (Bordeaux wine region). Some words carry the circumflex accent (â) in French; this disappears in English but the spelling stays."},"lc-u76-4":{"src":"concept:50:cards:4","route":"#/stop/u76","cta":"Open this stop","title":"-eau ending (silent -x plural) · The Confusables","body":"Plateau (flat high area) vs plaque vs plait (braid) — completely different words. Bureau (desk/government office) vs burrow (a hole) — wildly different origins. When you see -eau, it is always French, always /oh/, and always distinct from any similar-sounding English word."},"uq-u76-0":{"src":"unit:u76:qs:0","route":"#/stop/u76","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “-eau ending (silent -x plural)”?","opts":["French words ending in -eau use the plural -eaux — the x is silent in both forms.","In English words of Greek origin, y functions as a vowel, sounding like /i/ or /ee/.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil."],"after":"From “-eau ending (silent -x plural)”."}},"uq-u76-3":{"src":"unit:u76:qs:3","route":"#/stop/u76","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁: a TABLE of living figures arranged like ART—the 'eau' is silent like a still painting” — which word is this hook about?","opts":["tableau","plateau","château","bureau"],"after":"From “-eau ending (silent -x plural)”."}},"wd-tableau":{"src":"concept:50:words:0:def","route":"#/word/tableau","cta":"Open the word card","title":"tableau","roman":"t-uh-b-l-OH","body":"a group of people attractively arranged (as if in a painting)","clip":1},"wx-tableau":{"src":"concept:50:words:0:ex","route":"#/word/tableau","cta":"Open the word card","title":"In a sentence · tableau","body":"The drama students created a stunning tableau representing the signing of the Declaration of Independence, holding perfectly still for thirty seconds.","clip":1},"wh-tableau":{"src":"concept:50:words:0:hook","route":"#/word/tableau","cta":"Open the word card","title":"Remember it · tableau","body":"TABLEAU: a TABLE of living figures arranged like ART—the 'eau' is silent like a still painting"},"wo-tableau":{"src":"lore:tableau:0","route":"#/word/tableau","cta":"Open the word card","title":"Where it comes from · tableau","body":"French tableau = picture, board, diminutive of table(slab, board, from Latin tabula)"},"wx-plateau":{"src":"concept:50:words:1:ex","route":"#/word/plateau","cta":"Open the word card","title":"In a sentence · plateau","body":"The hikers rested on the wide plateau and gazed at the sweeping valley far below them.","clip":1},"wh-plateau":{"src":"concept:50:words:1:hook","route":"#/word/plateau","cta":"Open the word card","title":"Remember it · plateau","body":"A PLATEAU has a flat top spelled with -EAU at the end — think of the French word for water (eau) pooling on flat land."},"wo-plateau":{"src":"lore:plateau:0","route":"#/word/plateau","cta":"Open the word card","title":"Where it comes from · plateau","body":"French plateau = flat elevated land, from Old French platel = flat"},"wd-bureau":{"src":"concept:50:words:3:def","route":"#/word/bureau","cta":"Open the word card","title":"bureau","roman":"BYUU-roh","body":"an administrative unit of government","clip":1},"wx-bureau":{"src":"concept:50:words:3:ex","route":"#/word/bureau","cta":"Open the word card","title":"In a sentence · bureau","body":"Every spring, the government census bureau counts how many people live in each town.","clip":1},"wh-bureau":{"src":"concept:50:words:3:hook","route":"#/word/bureau","cta":"Open the word card","title":"Remember it · bureau","body":"BUREAU ends in -EAU, the French word for water — let that fancy French ending FLOW: bur-EAU."},"wx-trousseau":{"src":"concept:50:words:4:ex","route":"#/word/trousseau","cta":"Open the word card","title":"In a sentence · trousseau","body":"Her grandmother spent months carefully embroidering linens for her trousseau before the wedding day arrived.","clip":1},"wh-trousseau":{"src":"concept:50:words:4:hook","route":"#/word/trousseau","cta":"Open the word card","title":"Remember it · trousseau","body":"TROUSSEAU has double S like a bride's double joy — trouSSeau, and ends in the fancy French -EAU."},"wo-trousseau":{"src":"lore:trousseau:0","route":"#/word/trousseau","cta":"Open the word card","title":"Where it comes from · trousseau","body":"French trousseau = bundle, diminutive of trousse = bundle"},"wd-gateau":{"src":"concept:50:words:5:def","route":"#/word/gateau","cta":"Open the word card","title":"gateau","roman":"gah-TOH","body":"any of various rich and elaborate cakes","clip":1},"wx-gateau":{"src":"concept:50:words:5:ex","route":"#/word/gateau","cta":"Open the word card","title":"In a sentence · gateau","body":"The bakery displayed a stunning chocolate gateau layered with cream and fresh raspberries in the window.","clip":1},"wh-gateau":{"src":"concept:50:words:5:hook","route":"#/word/gateau","cta":"Open the word card","title":"Remember it · gateau","body":"A gateau ends in -EAU like 'château'—rich cakes belong in fancy French châteaux."},"wd-flambeau":{"src":"concept:50:words:6:def","route":"#/word/flambeau","cta":"Open the word card","title":"flambeau","roman":"FLAM-boh","body":"a flaming torch (such as are used in processions at night)","clip":1},"wx-flambeau":{"src":"concept:50:words:6:ex","route":"#/word/flambeau","cta":"Open the word card","title":"In a sentence · flambeau","body":"The masked marcher held a glowing flambeau high above his head as the Mardi Gras parade wound through the dark streets.","clip":1},"wh-flambeau":{"src":"concept:50:words:6:hook","route":"#/word/flambeau","cta":"Open the word card","title":"Remember it · flambeau","body":"A FLAMBEAU torch glows like a beautiful EAU — remember the French -EAU ending."},"wx-nouveau":{"src":"concept:50:words:7:ex","route":"#/word/nouveau","cta":"Open the word card","title":"In a sentence · nouveau","body":"The nouveau restaurant served traditional dishes with unexpected modern twists that surprised every food critic in town.","clip":1},"wh-nouveau":{"src":"concept:50:words:7:hook","route":"#/word/nouveau","cta":"Open the word card","title":"Remember it · nouveau","body":"NOUVeau — think NOVEL and NEW — same root!"},"wd-beau":{"src":"concept:50:words:8:def","route":"#/word/beau","cta":"Open the word card","title":"beau","roman":"BOH","body":"a man who is the lover of a girl or young woman","clip":1},"wx-beau":{"src":"concept:50:words:8:ex","route":"#/word/beau","cta":"Open the word card","title":"In a sentence · beau","body":"In the old novel, Elizabeth's beau arrived with roses and asked her to the dance.","clip":1},"wh-beau":{"src":"concept:50:words:8:hook","route":"#/word/beau","cta":"Open the word card","title":"Remember it · beau","body":"Your BEAU is BEAUtiful — the first four letters of beautiful spell your beau: b-e-a-u."},"wd-rondeau":{"src":"concept:50:words:9:def","route":"#/word/rondeau","cta":"Open the word card","title":"rondeau","roman":"rah-NDOH","body":"a musical form that is often the last movement of a sonata","clip":1},"wx-rondeau":{"src":"concept:50:words:9:ex","route":"#/word/rondeau","cta":"Open the word card","title":"In a sentence · rondeau","body":"The pianist finished the recital with a spirited rondeau that had the audience clapping along by the final bars.","clip":1},"wh-rondeau":{"src":"concept:50:words:9:hook","route":"#/word/rondeau","cta":"Open the word card","title":"Remember it · rondeau","body":"RONDEAU — ROND means ROUND, like music that circles back to the beginning"},"wo-rondeau":{"src":"lore:rondeau:0","route":"#/word/rondeau","cta":"Open the word card","title":"Where it comes from · rondeau","body":"French rondeau = a round, from rond = round, circle"},"wd-morceau":{"src":"concept:50:words:11:def","route":"#/word/morceau","cta":"Open the word card","title":"morceau","roman":"mor-SOH","body":"a short literary or musical composition","clip":1},"wx-morceau":{"src":"concept:50:words:11:ex","route":"#/word/morceau","cta":"Open the word card","title":"In a sentence · morceau","body":"The pianist performed a delicate morceau that moved the small audience to tears.","clip":1},"wh-morceau":{"src":"concept:50:words:11:hook","route":"#/word/morceau","cta":"Open the word card","title":"Remember it · morceau","body":"A MORCEAU is a musical morsel — think of it as a tiny BITE (MORS) of music ending in the fancy French -EAU."},"wx-tableaux":{"src":"concept:50:words:15:ex","route":"#/word/tableaux","cta":"Open the word card","title":"In a sentence · tableaux","body":"The drama students created stunning tableaux to represent key scenes from the history of ancient Rome.","clip":1},"wh-tableaux":{"src":"concept:50:words:15:hook","route":"#/word/tableaux","cta":"Open the word card","title":"Remember it · tableaux","body":"TABLEAUX ends in -eaux like bordeaux wine — beautiful French paintings need a French plural."},"wd-plateaux":{"src":"concept:50:words:16:def","route":"#/word/plateaux","cta":"Open the word card","title":"plateaux","roman":"pla-TOHZ","body":"a relatively flat highland","clip":1},"wx-plateaux":{"src":"concept:50:words:16:ex","route":"#/word/plateaux","cta":"Open the word card","title":"In a sentence · plateaux","body":"The French geographers mapped the vast plateaux that stretched across the interior of the continent.","clip":1},"wh-plateaux":{"src":"concept:50:words:16:hook","route":"#/word/plateaux","cta":"Open the word card","title":"Remember it · plateaux","body":"The French keep the X in plateaux, just as they keep the X in beaux — fancy flat endings for fancy flat lands."},"li-u77":{"src":"concept:51:concept","route":"#/stop/u77","cta":"Open this stop","title":"-oir / -oire (French vowel ending)","body":"French words ending in -oir or -oire carry their French spelling into English intact. The -oir sounds like /wahr/ — a distinctively French pattern impossible to guess without knowing it."},"lc-u77-0":{"src":"concept:51:cards:0","route":"#/stop/u77","cta":"Open this stop","title":"-oir / -oire (French vowel ending) · The -oir Pattern","body":"French -oir = /wahr/ sound. Boudoir (bouder = to sulk) = a private sitting room. Abattoir (abattre = to strike down) = a slaughterhouse. Peignoir (peigner = to comb) = a lightweight dressing gown. Armoire (armarium = cupboard) = a tall wardrobe. The -oir ending is unmistakably French."},"lc-u77-1":{"src":"concept:51:cards:1","route":"#/stop/u77","cta":"Open this stop","title":"-oir / -oire (French vowel ending) · More -oir/-oire Words","body":"Reservoir (réserver) = a lake storing water — R-E-S-E-R-V-O-I-R. Memoir (mémoire = memory) = a personal narrative. Repertoire (répertoire = inventory) = a known set of works — R-E-P-E-R-T-O-I-R-E (keeps the final e in American English). Conservatoire = a music school (British usage)."},"lc-u77-2":{"src":"concept:51:cards:2","route":"#/stop/u77","cta":"Open this stop","title":"-oir / -oire (French vowel ending) · Memory Trick","body":"The -oir ending sounds like the English word \"war\" with a /w/ added: /wahr/. So boudoir = BOO + d + war = BOO-dwahr. Abattoir = uh-BAT + war = uh-BAT-wahr. Once you hear the /wahr/ ending, the -oir spelling becomes automatic."},"lc-u77-3":{"src":"concept:51:cards:3","route":"#/stop/u77","cta":"Open this stop","title":"-oir / -oire (French vowel ending) · Reservoir Spelling Detail","body":"R-E-S-E-R-V-O-I-R — the -oir at the end, not -oire. Note the vowel sequence: E-R-V-O-I-R. Many misspell this as resevoir (dropping the r) or reservoire (adding an e). Say it syllable by syllable: res · er · voir — three clean syllables."},"lc-u77-4":{"src":"concept:51:cards:4","route":"#/stop/u77","cta":"Open this stop","title":"-oir / -oire (French vowel ending) · -oire Variant","body":"Some French words keep -oire in American English: repertoire (R-E-P-E-R-T-O-I-R-E), conservatoire. Others drop the final e: reservoir, memoir. When in doubt, the question \"What language does this word come from?\" at the microphone = French → prepare for -oir or -oire."},"uq-u77-3":{"src":"unit:u77:qs:3","route":"#/stop/u77","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A ▁▁▁ is where a lady goes to BROOD — bouder means to sulk, and the -oir is her private place.” — which word is this hook about?","opts":["boudoir","abattoir","peignoir","armoire"],"after":"From “-oir / -oire (French vowel ending)”."}},"wx-boudoir":{"src":"concept:51:words:0:ex","route":"#/word/boudoir","cta":"Open the word card","title":"In a sentence · boudoir","body":"The duchess retreated to her boudoir each evening to write letters and read by candlelight.","clip":1},"wh-boudoir":{"src":"concept:51:words:0:hook","route":"#/word/boudoir","cta":"Open the word card","title":"Remember it · boudoir","body":"A BOUDOIR is where a lady goes to BROOD — bouder means to sulk, and the -oir is her private place."},"wo-boudoir":{"src":"lore:boudoir:0","route":"#/word/boudoir","cta":"Open the word card","title":"Where it comes from · boudoir","body":"French bouder = to sulk, pout"},"wd-abattoir":{"src":"concept:51:words:1:def","route":"#/word/abattoir","cta":"Open the word card","title":"abattoir","roman":"a-buh-TWAHR","body":"A slaughterhouse; a place where animals are killed for food on a large scale.","clip":1},"wx-abattoir":{"src":"concept:51:words:1:ex","route":"#/word/abattoir","cta":"Open the word card","title":"In a sentence · abattoir","body":"The journalist's expose revealed unsanitary conditions at the abattoir that were shocking to consumers who had never considered where their meat came from.","clip":1},"wh-abattoir":{"src":"concept:51:words:1:hook","route":"#/word/abattoir","cta":"Open the word card","title":"Remember it · abattoir","body":"ABATTOIR has double-t—two t's like two blades in a slaughterhouse"},"wo-abattoir":{"src":"lore:abattoir:0","route":"#/word/abattoir","cta":"Open the word card","title":"Where it comes from · abattoir","body":"French abattre meaning to beat down, slaughter"},"wx-peignoir":{"src":"concept:51:words:2:ex","route":"#/word/peignoir","cta":"Open the word card","title":"In a sentence · peignoir","body":"She slipped into her silk peignoir and settled into the armchair beside the window to read her novel.","clip":1},"wh-peignoir":{"src":"concept:51:words:2:hook","route":"#/word/peignoir","cta":"Open the word card","title":"Remember it · peignoir","body":"A PEIGNOIR is worn while combing your hair — the GN hides silently like a comb tucked in a robe pocket."},"wo-peignoir":{"src":"lore:peignoir:0","route":"#/word/peignoir","cta":"Open the word card","title":"Where it comes from · peignoir","body":"French peigner = to comb hair, from Latin pectinare = to comb"},"wx-armoire":{"src":"concept:51:words:3:ex","route":"#/word/armoire","cta":"Open the word card","title":"In a sentence · armoire","body":"She discovered her grandmother's old love letters hidden at the back of the towering oak armoire.","clip":1},"wh-armoire":{"src":"concept:51:words:3:hook","route":"#/word/armoire","cta":"Open the word card","title":"Remember it · armoire","body":"An armOIRE stores your wardrobe — think 'OIR' as in French 'voir' (to see) what you'll wear today."},"wo-armoire":{"src":"lore:armoire:0","route":"#/word/armoire","cta":"Open the word card","title":"Where it comes from · armoire","body":"French armoire = cupboard, from Latin armarium = chest for arms/tools"},"wx-reservoir":{"src":"concept:51:words:4:ex","route":"#/word/reservoir","cta":"Open the word card","title":"In a sentence · reservoir","body":"a reservoir of talent","clip":1},"wh-reservoir":{"src":"concept:51:words:4:hook","route":"#/word/reservoir","cta":"Open the word card","title":"Remember it · reservoir","body":"A reserVOIR ends in -VOIR (French for 'see') — au reVOIR, see you at the water reservoir!"},"wo-reservoir":{"src":"lore:reservoir:0","route":"#/word/reservoir","cta":"Open the word card","title":"Where it comes from · reservoir","body":"French réservoir = storehouse, from réserver = to keep"},"wx-memoir":{"src":"concept:51:words:5:ex","route":"#/word/memoir","cta":"Open the word card","title":"In a sentence · memoir","body":"The retired astronaut wrote a gripping memoir about her harrowing journey aboard the damaged space shuttle.","clip":1},"wh-memoir":{"src":"concept:51:words:5:hook","route":"#/word/memoir","cta":"Open the word card","title":"Remember it · memoir","body":"A MEMOIR is a MEMory told with French flair — spell the French ending 'o-i-r', not 'i-o-r'."},"wo-memoir":{"src":"lore:memoir:0","route":"#/word/memoir","cta":"Open the word card","title":"Where it comes from · memoir","body":"French mémoire = memory, from Latin memoria"},"wd-repertoire":{"src":"concept:51:words:6:def","route":"#/word/repertoire","cta":"Open the word card","title":"repertoire","roman":"REH-per-twahr","body":"the entire range of skills or aptitudes or devices used in a particular field or occupation","clip":1},"wx-repertoire":{"src":"concept:51:words:6:ex","route":"#/word/repertoire","cta":"Open the word card","title":"In a sentence · repertoire","body":"Her piano repertoire includes twelve pieces she can play from memory without one mistake.","clip":1},"wh-repertoire":{"src":"concept:51:words:6:hook","route":"#/word/repertoire","cta":"Open the word card","title":"Remember it · repertoire","body":"rePERTOIRE ends in -OIRE like a French soirée — a collection you perform at every evening event."},"wo-repertoire":{"src":"lore:repertoire:0","route":"#/word/repertoire","cta":"Open the word card","title":"Where it comes from · repertoire","body":"Latin repertorium = inventory (reperire = to find again)"},"li-u78":{"src":"concept:52:concept","route":"#/stop/u78","cta":"Open this stop","title":"-ette (French diminutive)","body":"French -ette = a small version of something (diminutive). Always double-t, always ends in silent -e. Once you see the pattern, every -ette word spells itself."},"lc-u78-0":{"src":"concept:52:cards:0","route":"#/stop/u78","cta":"Open this stop","title":"-ette (French diminutive) · The -ette Diminutive","body":"French -ette makes things smaller or more delicate. Pirouette = a spinning turn. Marionette = a small puppet (originally \"little Mary\"). Palette (pale = shovel) = a small flat surface for colors. Layette = a set of small baby clothes. Coquette = a flirtatious woman. Silhouette = a dark outline."},"lc-u78-1":{"src":"concept:52:cards:1","route":"#/stop/u78","cta":"Open this stop","title":"-ette (French diminutive) · -ette for Compositions","body":"Vignette (vigne = vine) = a brief literary sketch. Roulette (rouler = roll) = little rolling wheel. Serviette = a small serving cloth = napkin. Brunette = having brown hair. Rosette = a rose-shaped decoration. Cassette = a small case. Etiquette = the small rules of polite behavior."},"lc-u78-2":{"src":"concept:52:cards:2","route":"#/stop/u78","cta":"Open this stop","title":"-ette (French diminutive) · Always Double-T","body":"The -ette ending always has double-t: P-I-R-O-U-E-T-T-E, never pirouete. The -tt- comes from the French diminutive form. ⚠️ Confetti (Italian, not French) = C-O-N-F-E-T-T-I — double-t here is Italian diminutive, not the French -ette pattern. Different language, same doubling instinct."},"lc-u78-3":{"src":"concept:52:cards:3","route":"#/stop/u78","cta":"Open this stop","title":"-ette (French diminutive) · -ette vs -et (Single-t)","body":"Some French words end in -et (single-t, silent final t): buffet, bouquet, ballet, ricochet, crochet. The -ette words have a pronounced vowel before the final t: pi-roo-ET (you hear the vowel). The -et words have a stressed vowel that ends the word: boo-KAY (the t is silent)."},"lc-u78-4":{"src":"concept:52:cards:4","route":"#/stop/u78","cta":"Open this stop","title":"-ette (French diminutive) · Championship -ette Words","body":"Epaulette (épaule = shoulder) = a shoulder decoration on a uniform. Lorgnette (lorgner = to spy) = a pair of glasses on a handle. Marionette = M-A-R-I-O-N-E-T-T-E. Pirouette = P-I-R-O-U-E-T-T-E. Silhouette = S-I-L-H-O-U-E-T-T-E (silent h as well as double-t)."},"uq-u78-0":{"src":"unit:u78:qs:0","route":"#/stop/u78","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “-ette (French diminutive)”?","opts":["French -ette = a small version of something (diminutive).","In English words of Greek origin, y functions as a vowel, sounding like /i/ or /ee/.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil."],"after":"From “-ette (French diminutive)”."}},"uq-u78-3":{"src":"unit:u78:qs:3","route":"#/stop/u78","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ has FOUR vowels in a row (ouet) — the dancer spins four times before sticking the landing.” — which word is this hook about?","opts":["pirouette","marionette","palette","layette"],"after":"From “-ette (French diminutive)”."}},"wx-pirouette":{"src":"concept:52:words:0:ex","route":"#/word/pirouette","cta":"Open the word card","title":"In a sentence · pirouette","body":"The ballerina completed a flawless pirouette at center stage, spinning so fast she seemed to blur.","clip":1},"wh-pirouette":{"src":"concept:52:words:0:hook","route":"#/word/pirouette","cta":"Open the word card","title":"Remember it · pirouette","body":"PIROUETTE has FOUR vowels in a row (ouet) — the dancer spins four times before sticking the landing."},"wo-pirouette":{"src":"lore:pirouette:0","route":"#/word/pirouette","cta":"Open the word card","title":"Where it comes from · pirouette","body":"French pirouette = spinning top"},"wd-marionette":{"src":"concept:52:words:1:def","route":"#/word/marionette","cta":"Open the word card","title":"marionette","roman":"mair-ee-uh-NET","body":"a small figure of a person operated from above with strings by a puppeteer","clip":1},"wx-marionette":{"src":"concept:52:words:1:ex","route":"#/word/marionette","cta":"Open the word card","title":"In a sentence · marionette","body":"The marionette's wooden legs clattered on the tiny stage as the puppeteer made it dance a jig.","clip":1},"wh-marionette":{"src":"concept:52:words:1:hook","route":"#/word/marionette","cta":"Open the word card","title":"Remember it · marionette","body":"Little MARION dances on a stage — mariONETTE"},"wo-marionette":{"src":"lore:marionette:0","route":"#/word/marionette","cta":"Open the word card","title":"Where it comes from · marionette","body":"French Marion = diminutive of Marie"},"wx-palette":{"src":"concept:52:words:2:ex","route":"#/word/palette","cta":"Open the word card","title":"In a sentence · palette","body":"The artist squeezed bright colors onto her palette before painting the sunset.","clip":1},"wh-palette":{"src":"concept:52:words:2:hook","route":"#/word/palette","cta":"Open the word card","title":"Remember it · palette","body":"A PALETTE has one 'l' and ends in -ette — remember: one layer of paint needs one 'l,' then -ette like 'kitchenette.'"},"wo-palette":{"src":"lore:palette:0","route":"#/word/palette","cta":"Open the word card","title":"Where it comes from · palette","body":"French palette = small shovel, diminutive of pale = shovel"},"wx-layette":{"src":"concept:52:words:3:ex","route":"#/word/layette","cta":"Open the word card","title":"In a sentence · layette","body":"Grandma knitted several tiny sweaters to add to the layette she was preparing for the new arrival.","clip":1},"wh-layette":{"src":"concept:52:words:3:hook","route":"#/word/layette","cta":"Open the word card","title":"Remember it · layette","body":"A layETTE for a baby — think of a little French box (ETTE) where you LAY the newborn's clothes."},"wo-layette":{"src":"lore:layette:0","route":"#/word/layette","cta":"Open the word card","title":"Where it comes from · layette","body":"French layette = drawer, baby clothes box"},"wx-silhouette":{"src":"concept:52:words:5:ex","route":"#/word/silhouette","cta":"Open the word card","title":"In a sentence · silhouette","body":"As the sun set behind the mountains, the silhouette of the ancient castle appeared dramatically against the glowing orange sky.","clip":1},"wh-silhouette":{"src":"concept:52:words:5:hook","route":"#/word/silhouette","cta":"Open the word card","title":"Remember it · silhouette","body":"silHOUette — the HOUSE makes a silhouette against the sky; remember -ETTE at the end (double T, final E)."},"wo-silhouette":{"src":"lore:silhouette:0","route":"#/word/silhouette","cta":"Open the word card","title":"Where it comes from · silhouette","body":"Named after Étienne de Silhouette, an 18th-century French finance minister known for cheap policies and outline portraits"},"wd-vignette":{"src":"concept:52:words:6:def","route":"#/word/vignette","cta":"Open the word card","title":"vignette","roman":"vih-NYEHT","body":"a brief literary description","clip":1},"wx-vignette":{"src":"concept:52:words:6:ex","route":"#/word/vignette","cta":"Open the word card","title":"In a sentence · vignette","body":"The author opened her novel with a vignette of a girl watching fireflies, instantly drawing readers into the story's dreamy mood.","clip":1},"wh-vignette":{"src":"concept:52:words:6:hook","route":"#/word/vignette","cta":"Open the word card","title":"Remember it · vignette","body":"viGNETTE has a silent 'g' — like a vine growing quietly."},"wo-vignette":{"src":"lore:vignette:0","route":"#/word/vignette","cta":"Open the word card","title":"Where it comes from · vignette","body":"French vigne = vine; originally a decoration of vine leaves on a page border"},"wx-roulette":{"src":"concept:52:words:7:ex","route":"#/word/roulette","cta":"Open the word card","title":"In a sentence · roulette","body":"The players gathered around the spinning roulette wheel, each hoping the ball would land on their chosen number.","clip":1},"wh-roulette":{"src":"concept:52:words:7:hook","route":"#/word/roulette","cta":"Open the word card","title":"Remember it · roulette","body":"ROULETTE is a little wheel — the -ETTE ending spins like the wheel, one T before the E, never two."},"wo-roulette":{"src":"lore:roulette:0","route":"#/word/roulette","cta":"Open the word card","title":"Where it comes from · roulette","body":"French roulette = little wheel, from roue = wheel"},"wd-brunette":{"src":"concept:52:words:9:def","route":"#/word/brunette","cta":"Open the word card","title":"brunette","roman":"broo-NEHT","body":"a person with dark (brown) hair","clip":1},"wx-brunette":{"src":"concept:52:words:9:ex","route":"#/word/brunette","cta":"Open the word card","title":"In a sentence · brunette","body":"The lead actress in the school play was a tall brunette whose dark, glossy hair cascaded past her shoulders and caught the stage lights whenever she turned her head dramatically.","clip":1},"wh-brunette":{"src":"concept:52:words:9:hook","route":"#/word/brunette","cta":"Open the word card","title":"Remember it · brunette","body":"BRUNETTE is feminine — she gets double T and an E, like a little extra flair."},"wd-rosette":{"src":"concept:52:words:10:def","route":"#/word/rosette","cta":"Open the word card","title":"rosette","roman":"ruh-SEHT","body":"an ornament or pattern resembling a rose that is worn as a badge of office or as recognition of having won an honor","clip":1},"wx-rosette":{"src":"concept:52:words:10:ex","route":"#/word/rosette","cta":"Open the word card","title":"In a sentence · rosette","body":"The winning horse wore a bright blue rosette pinned proudly to its bridle.","clip":1},"wh-rosette":{"src":"concept:52:words:10:hook","route":"#/word/rosette","cta":"Open the word card","title":"Remember it · rosette","body":"A roSETTE is a little rose you SET on your lapel — one S, double T."},"wd-cassette":{"src":"concept:52:words:11:def","route":"#/word/cassette","cta":"Open the word card","title":"cassette","roman":"kuh-SEHT","body":"a container that holds a magnetic tape used for recording or playing sound or video","clip":1},"wx-cassette":{"src":"concept:52:words:11:ex","route":"#/word/cassette","cta":"Open the word card","title":"In a sentence · cassette","body":"He found an old cassette of his favorite band tucked away in a dusty shoebox.","clip":1},"wh-cassette":{"src":"concept:52:words:11:hook","route":"#/word/cassette","cta":"Open the word card","title":"Remember it · cassette","body":"CASSETTE has double-S and double-T: two S's for the two spools of tape spinning inside."},"wd-epaulette":{"src":"concept:52:words:12:def","route":"#/word/epaulette","cta":"Open the word card","title":"epaulette","roman":"EP-uh-let","body":"adornment consisting of an ornamental cloth pad worn on the shoulder","clip":1},"wx-epaulette":{"src":"concept:52:words:12:ex","route":"#/word/epaulette","cta":"Open the word card","title":"In a sentence · epaulette","body":"Each officer wore a silver epaulette on his right shoulder to show his rank.","clip":1},"wh-epaulette":{"src":"concept:52:words:12:hook","route":"#/word/epaulette","cta":"Open the word card","title":"Remember it · epaulette","body":"Epaulette has a double T at the end — two tassels dangling from that fancy shoulder pad."},"wo-epaulette":{"src":"lore:epaulette:0","route":"#/word/epaulette","cta":"Open the word card","title":"Where it comes from · epaulette","body":"French épaule=shoulder + diminutive -ette"},"wd-lorgnette":{"src":"concept:52:words:13:def","route":"#/word/lorgnette","cta":"Open the word card","title":"lorgnette","roman":"law-RNYEHT","body":"eyeglasses that are held to the eyes with a long handle","clip":1},"wx-lorgnette":{"src":"concept:52:words:13:ex","route":"#/word/lorgnette","cta":"Open the word card","title":"In a sentence · lorgnette","body":"The opera patron raised her lorgnette to study the performers on the distant stage.","clip":1},"wh-lorgnette":{"src":"concept:52:words:13:hook","route":"#/word/lorgnette","cta":"Open the word card","title":"Remember it · lorgnette","body":"A LORGNETTE lets you LORN-YET see who's across the room — keep the silent GN and double-T with -ETTE."},"wx-etiquette":{"src":"concept:52:words:14:ex","route":"#/word/etiquette","cta":"Open the word card","title":"In a sentence · etiquette","body":"Before the formal dinner, the students attended a class on table etiquette so they would know which fork to use for each course.","clip":1},"wh-etiquette":{"src":"concept:52:words:14:hook","route":"#/word/etiquette","cta":"Open the word card","title":"Remember it · etiquette","body":"ETIQUETTE has a DOUBLE T at the end — it takes TWO T's of effort to have good manners."},"wo-etiquette":{"src":"lore:etiquette:0","route":"#/word/etiquette","cta":"Open the word card","title":"Where it comes from · etiquette","body":"French étiquette=ticket, label, prescribed behavior"},"wd-statuette":{"src":"concept:52:words:15:def","route":"#/word/statuette","cta":"Open the word card","title":"statuette","roman":"sta-choo-EHT","body":"a small carved or molded figure","clip":1},"wx-statuette":{"src":"concept:52:words:15:ex","route":"#/word/statuette","cta":"Open the word card","title":"In a sentence · statuette","body":"She won a tiny golden statuette at the regional drama competition and kept it on her desk.","clip":1},"wh-statuette":{"src":"concept:52:words:15:hook","route":"#/word/statuette","cta":"Open the word card","title":"Remember it · statuette","body":"A statuETTE is a little statue — the '-ette' ending (double 't') means small, like a petite figurine."},"wo-statuette":{"src":"lore:statuette:0","route":"#/word/statuette","cta":"Open the word card","title":"Where it comes from · statuette","body":"French statuette = little statue, diminutive of statue"},"li-u79":{"src":"concept:53:concept","route":"#/stop/u79","cta":"Open this stop","title":"-esque / -ique / -que (French endings)","body":"Three French/Italian-derived endings giving English some of its most distinctive-looking words. Silent -e at the end; qu sounds like /k/. These patterns are completely regular once learned."},"lc-u79-0":{"src":"concept:53:cards:0","route":"#/stop/u79","cta":"Open this stop","title":"-esque / -ique / -que (French endings) · -esque = In the Style Of","body":"Italian -esco → French -esque → English. Picturesque = like a picture = visually charming. Grotesque (grotta = cave/grotto) = bizarre and distorted. Arabesque = in the Arabic style. Burlesque = comic theatrical style. Statuesque = like a statue = impressively tall."},"lc-u79-1":{"src":"concept:53:cards:1","route":"#/stop/u79","cta":"Open this stop","title":"-esque / -ique / -que (French endings) · -ique = French Origin Signal","body":"-ique words come from French. Boutique = a small specialty shop. Mystique = an air of mystery. Technique = a method. Physique = body structure. Antique = an old object. Unique = the only one of its kind. Oblique = slanting. All pronounced with /eek/ at the end — B-O-U-T-I-Q-U-E."},"lc-u79-2":{"src":"concept:53:cards:2","route":"#/stop/u79","cta":"Open this stop","title":"-esque / -ique / -que (French endings) · -que at the End","body":"Rare but important: opaque (opacus = shaded) = does not allow light through. Plaque = a flat commemorative sign. Torque (torquere = to twist) = rotational force. Clique = a small exclusive group. The -que without a preceding -i- appears in only a few words."},"lc-u79-3":{"src":"concept:53:cards:3","route":"#/stop/u79","cta":"Open this stop","title":"-esque / -ique / -que (French endings) · The qu Rule","body":"In all three endings, q is ALWAYS followed by u. English never has q without u — except in borrowed words like qi, qigong, qanat. For all -esque/-ique/-que words: always write qu, never just q. This is one of the most reliable spelling rules in English."},"lc-u79-4":{"src":"concept:53:cards:4","route":"#/stop/u79","cta":"Open this stop","title":"-esque / -ique / -que (French endings) · High-Value Championship Words","body":"Arabesque = A-R-A-B-E-S-Q-U-E (often misspelled arbaesque). Grotesque = G-R-O-T-E-S-Q-U-E. Mystique = M-Y-S-T-I-Q-U-E (note the y = vowel). Technique = T-E-C-H-N-I-Q-U-E (-ch- = /k/ from Greek tekhnē through French). Unique = U-N-I-Q-U-E — only one u at the start."},"uq-u79-0":{"src":"unit:u79:qs:0","route":"#/stop/u79","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “-esque / -ique / -que (French endings)”?","opts":["Three French/Italian-derived endings giving English some of its most distinctive-looking words.","In English words of Greek origin, y functions as a vowel, sounding like /i/ or /ee/.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil."],"after":"From “-esque / -ique / -que (French endings)”."}},"uq-u79-3":{"src":"unit:u79:qs:3","route":"#/stop/u79","cta":"Open this stop","title":"Whose hook?","play":{"q":"“A scene so pretty it belongs in a picture—add -ESQUE like a French flair at the end.” — which word is this hook about?","opts":["picturesque","grotesque","arabesque","burlesque"],"after":"From “-esque / -ique / -que (French endings)”."}},"wx-picturesque":{"src":"concept:53:words:0:ex","route":"#/word/picturesque","cta":"Open the word card","title":"In a sentence · picturesque","body":"a picturesque village","clip":1},"wh-picturesque":{"src":"concept:53:words:0:hook","route":"#/word/picturesque","cta":"Open the word card","title":"Remember it · picturesque","body":"A scene so pretty it belongs in a picture—add -ESQUE like a French flair at the end."},"wo-picturesque":{"src":"lore:picturesque:0","route":"#/word/picturesque","cta":"Open the word card","title":"Where it comes from · picturesque","body":"French pittoresque = like a picture"},"wx-grotesque":{"src":"concept:53:words:1:ex","route":"#/word/grotesque","cta":"Open the word card","title":"In a sentence · grotesque","body":"tales of grotesque serpents eight fathoms long that churned the seas","clip":1},"wh-grotesque":{"src":"concept:53:words:1:hook","route":"#/word/grotesque","cta":"Open the word card","title":"Remember it · grotesque","body":"GROTESQUE art was found in GROTTO caves — grot+esque, ending in the fancy French -ESQUE."},"wo-grotesque":{"src":"lore:grotesque:0","route":"#/word/grotesque","cta":"Open the word card","title":"Where it comes from · grotesque","body":"Italian grottesca = cave painting, from grotta = cave"},"wd-arabesque":{"src":"concept:53:words:2:def","route":"#/word/arabesque","cta":"Open the word card","title":"arabesque","roman":"ar-ah-BESK","body":"position in which the dancer has one leg raised behind and arms outstretched in a conventional pose","clip":1},"wx-arabesque":{"src":"concept:53:words:2:ex","route":"#/word/arabesque","cta":"Open the word card","title":"In a sentence · arabesque","body":"The ballerina held a flawless arabesque for several breathtaking seconds, her back leg perfectly parallel to the stage.","clip":1},"wh-arabesque":{"src":"concept:53:words:2:hook","route":"#/word/arabesque","cta":"Open the word card","title":"Remember it · arabesque","body":"Arabesque ends in -ESQUE like 'picturesque' — a beautifully posed, picture-like position."},"wo-arabesque":{"src":"lore:arabesque:0","route":"#/word/arabesque","cta":"Open the word card","title":"Where it comes from · arabesque","body":"French arabesque from Italian arabesco = in the Arabic style (Arabo = Arab)"},"wd-burlesque":{"src":"concept:53:words:3:def","route":"#/word/burlesque","cta":"Open the word card","title":"burlesque","roman":"ber-LEHSK","body":"a funny stage show that makes something serious look silly by exaggerating it","clip":1},"wx-burlesque":{"src":"concept:53:words:3:ex","route":"#/word/burlesque","cta":"Open the word card","title":"In a sentence · burlesque","body":"Our drama club performed a burlesque of the evening news, exaggerating every reporter's serious frown.","clip":1},"wh-burlesque":{"src":"concept:53:words:3:hook","route":"#/word/burlesque","cta":"Open the word card","title":"Remember it · burlesque","body":"BURLESQUE ends in '-que' like a French joke — picture a clown asking 'What's the ESQUE of this?' with a wink."},"wd-statuesque":{"src":"concept:53:words:4:def","route":"#/word/statuesque","cta":"Open the word card","title":"statuesque","roman":"sta-choo-EHSK","body":"of size and dignity suggestive of a statue","clip":1},"wx-statuesque":{"src":"concept:53:words:4:ex","route":"#/word/statuesque","cta":"Open the word card","title":"In a sentence · statuesque","body":"The statuesque player towered over the other students at tryouts, moving with an effortless, graceful stride.","clip":1},"wh-statuesque":{"src":"concept:53:words:4:hook","route":"#/word/statuesque","cta":"Open the word card","title":"Remember it · statuesque","body":"STATUESQUE ends in -ESQUE like grotESQUE — noble and grand!"},"wo-statuesque":{"src":"lore:statuesque:0","route":"#/word/statuesque","cta":"Open the word card","title":"Where it comes from · statuesque","body":"Latin statua = statue, from statuere = to set up"},"wx-boutique":{"src":"concept:53:words:5:ex","route":"#/word/boutique","cta":"Open the word card","title":"In a sentence · boutique","body":"She found the perfect dress at a tiny boutique tucked between a bakery and a bookstore on the cobblestone street.","clip":1},"wh-boutique":{"src":"concept:53:words:5:hook","route":"#/word/boutique","cta":"Open the word card","title":"Remember it · boutique","body":"A BOUTIQUE has a UNIQUE quality — spot the word UNIQUE hiding inside boUTIQUE."},"wo-boutique":{"src":"lore:boutique:0","route":"#/word/boutique","cta":"Open the word card","title":"Where it comes from · boutique","body":"French boutique = small shop, from Greek apotheke = storehouse"},"wx-mystique":{"src":"concept:53:words:6:ex","route":"#/word/mystique","cta":"Open the word card","title":"In a sentence · mystique","body":"The reclusive artist's mystique grew stronger with every painting she refused to sell or explain.","clip":1},"wh-mystique":{"src":"concept:53:words:6:hook","route":"#/word/mystique","cta":"Open the word card","title":"Remember it · mystique","body":"MYSTIQUE ends in QUE like a French boutique; she had the mystique of a chic French boutique."},"wo-mystique":{"src":"lore:mystique:0","route":"#/word/mystique","cta":"Open the word card","title":"Where it comes from · mystique","body":"French mystique = mysterious quality, from Greek mystikos"},"wd-physique":{"src":"concept:53:words:8:def","route":"#/word/physique","cta":"Open the word card","title":"physique","roman":"fuh-ZEEK","body":"constitution of the human body","clip":1},"wx-physique":{"src":"concept:53:words:8:ex","route":"#/word/physique","cta":"Open the word card","title":"In a sentence · physique","body":"Years of rowing gave Tom a strong physique with broad shoulders and steady arms.","clip":1},"wh-physique":{"src":"concept:53:words:8:hook","route":"#/word/physique","cta":"Open the word card","title":"Remember it · physique","body":"Your physique is unique — both end in '-que', a classy French flourish."},"wo-physique":{"src":"lore:physique:0","route":"#/word/physique","cta":"Open the word card","title":"Where it comes from · physique","body":"French physique = physical, from Greek physis = nature"},"wd-kafkaesque":{"src":"concept:53:words:15:def","route":"#/word/kafkaesque","cta":"Open the word card","title":"kafkaesque","roman":"kah-fkuh-EHSK","body":"relating to or in the manner of Franz Kafka or his writings","clip":1},"wx-kafkaesque":{"src":"concept:53:words:15:ex","route":"#/word/kafkaesque","cta":"Open the word card","title":"In a sentence · kafkaesque","body":"the kafkaesque terror of the endless interrogations","clip":1},"wh-kafkaesque":{"src":"concept:53:words:15:hook","route":"#/word/kafkaesque","cta":"Open the word card","title":"Remember it · kafkaesque","body":"Kafkaesque ends like grotesque — both describe something disturbingly strange: K-A-F-K-A-E-S-Q-U-E."},"wo-kafkaesque":{"src":"lore:kafkaesque:0","route":"#/word/kafkaesque","cta":"Open the word card","title":"Where it comes from · kafkaesque","body":"Czech surname Kafka + French -esque = in the style of"},"wd-romanesque":{"src":"concept:53:words:16:def","route":"#/word/romanesque","cta":"Open the word card","title":"romanesque","roman":"roh-muh-NEHSK","body":"a style of architecture developed in Italy and western Europe between the Roman and the Gothic styles after 1000 AD; characterized by round arches and vaults and by the substitution of piers for columns and profuse ornament and arcades","clip":1},"wx-romanesque":{"src":"concept:53:words:16:ex","route":"#/word/romanesque","cta":"Open the word card","title":"In a sentence · romanesque","body":"The old cathedral featured Romanesque arches and thick stone walls that had stood for nearly a thousand years.","clip":1},"wh-romanesque":{"src":"concept:53:words:16:hook","route":"#/word/romanesque","cta":"Open the word card","title":"Remember it · romanesque","body":"Romanesque arches look like a ROMAN's UNIQUE curved brow — end with -ESQUE like a grotesque gargoyle."},"wo-romanesque":{"src":"lore:romanesque:0","route":"#/word/romanesque","cta":"Open the word card","title":"Where it comes from · romanesque","body":"Latin Romanus = Roman + French -esque(in the style of)"},"li-u80":{"src":"concept:54:concept","route":"#/stop/u80","cta":"Open this stop","title":"French Silent Letters","body":"French words in English frequently carry silent final consonants — -t, -s, -x, -p, -d. These were once pronounced in Old French but fell silent while spelling was preserved. The result: some of English's trickiest words."},"lc-u80-0":{"src":"concept:54:cards:0","route":"#/stop/u80","cta":"Open this stop","title":"French Silent Letters · Silent Final -t","body":"Ballet (ba-LAY), bouquet (boo-KAY), crochet (kroh-SHAY), ricochet (RIK-uh-shay), parquet (par-KAY), valet (VAL-ay), buffet (buh-FAY), debut (day-BYOO). The -t is spelled, never pronounced. \"Spell what you don't hear\" is the French rule."},"lc-u80-1":{"src":"concept:54:cards:1","route":"#/stop/u80","cta":"Open this stop","title":"French Silent Letters · Silent Final -s","body":"Rendezvous (RON-day-voo), corps (kor — BOTH p AND s silent!), chassis (SHAS-ee), faux pas (FOH-PAH — two final consonants silent), debris (duh-BREE), fracas (FRAY-kus). These are borrowed exactly as written in French, where final -s was already silent."},"lc-u80-2":{"src":"concept:54:cards:2","route":"#/stop/u80","cta":"Open this stop","title":"French Silent Letters · The Double Silent — corps","body":"Corps = C-O-R-P-S — the p is silent AND the s is silent. Pronounced simply /KOR/. Plural corps is /KORZ/ — the s becomes voiced in the plural. Hors d'oeuvre = /or-DURV/ — the h, the s, and the final e are all silent. French truly is a language where silence rules the ends of words."},"lc-u80-3":{"src":"concept:54:cards:3","route":"#/stop/u80","cta":"Open this stop","title":"French Silent Letters · Silent -x","body":"In the -eau/-eaux pattern, the plural -x is always silent. Also: faux (FOH = false, as in faux fur). Beaux (BOH = plural of beau). In Old French, x was a shorthand abbreviation for s in plurals — the abbreviation became permanent in spelling but the s sound later fell silent."},"lc-u80-4":{"src":"concept:54:cards:4","route":"#/stop/u80","cta":"Open this stop","title":"French Silent Letters · Microphone Strategy at the Bee","body":"When you identify a word as French: (1) final consonants are probably silent, (2) stress falls on the LAST syllable (opposite of English), (3) vowels have French sounds. Ask \"What language does this word come from?\" If French, apply these three rules automatically before spelling."},"uq-u80-0":{"src":"unit:u80:qs:0","route":"#/stop/u80","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “French Silent Letters”?","opts":["French words in English frequently carry silent final consonants — -t, -s, -x, -p, -d.","In English words of Greek origin, y functions as a vowel, sounding like /i/ or /ee/.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil."],"after":"From “French Silent Letters”."}},"uq-u80-3":{"src":"unit:u80:qs:3","route":"#/stop/u80","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁ ends in -ET (silent T) like a French baguETte — the T is there but never heard.” — which word is this hook about?","opts":["ballet","bouquet","crochet","ricochet"],"after":"From “French Silent Letters”."}},"wx-crochet":{"src":"concept:54:words:2:ex","route":"#/word/crochet","cta":"Open the word card","title":"In a sentence · crochet","body":"Every evening, the grandmother would settle into her favorite armchair and crochet colorful blankets for the grandchildren, her hook moving so quickly that the yarn seemed to form patterns by magic.","clip":1},"wh-crochet":{"src":"concept:54:words:2:hook","route":"#/word/crochet","cta":"Open the word card","title":"Remember it · crochet","body":"CROCHET ends silently in -ET like a French beret — hook a loop and say 'shay'!"},"wo-crochet":{"src":"lore:crochet:0","route":"#/word/crochet","cta":"Open the word card","title":"Where it comes from · crochet","body":"French crochet = small hook, diminutive of croc = hook"},"wx-ricochet":{"src":"concept:54:words:3:ex","route":"#/word/ricochet","cta":"Open the word card","title":"In a sentence · ricochet","body":"One wild ricochet sent the ping-pong ball off the table leg and into my lap.","clip":1},"wh-ricochet":{"src":"concept:54:words:3:hook","route":"#/word/ricochet","cta":"Open the word card","title":"Remember it · ricochet","body":"RICOCHET ends in -CHET like a bouncing CATCH — it always comes back"},"wo-ricochet":{"src":"lore:ricochet:0","route":"#/word/ricochet","cta":"Open the word card","title":"Where it comes from · ricochet","body":"French ricochet = a skipping stone, of unknown further origin"},"wx-parquet":{"src":"concept:54:words:4:ex","route":"#/word/parquet","cta":"Open the word card","title":"In a sentence · parquet","body":"The ballroom in the historic mansion featured a gleaming parquet floor of alternating oak and cherry wood laid in a herringbone design.","clip":1},"wh-parquet":{"src":"concept:54:words:4:hook","route":"#/word/parquet","cta":"Open the word card","title":"Remember it · parquet","body":"PARQUET ends in -ET like a French word—it IS French, with a silent T"},"wo-parquet":{"src":"lore:parquet:0","route":"#/word/parquet","cta":"Open the word card","title":"Where it comes from · parquet","body":"French parquet = small enclosed space, diminutive of parc (park, enclosure)"},"wd-valet":{"src":"concept:54:words:5:def","route":"#/word/valet","cta":"Open the word card","title":"valet","roman":"va-LAY","body":"a manservant who acts as a personal attendant to his employer","clip":1},"wx-valet":{"src":"concept:54:words:5:ex","route":"#/word/valet","cta":"Open the word card","title":"In a sentence · valet","body":"Each morning the duke's valet laid out a fresh shirt and polished his riding boots.","clip":1},"wh-valet":{"src":"concept:54:words:5:hook","route":"#/word/valet","cta":"Open the word card","title":"Remember it · valet","body":"A valet parks your car with élan — the silent T at the end is très French, like ballet."},"wo-valet":{"src":"lore:valet:0","route":"#/word/valet","cta":"Open the word card","title":"Where it comes from · valet","body":"French valet = manservant, groom"},"wd-buffet":{"src":"concept:54:words:6:def","route":"#/word/buffet","cta":"Open the word card","title":"buffet","roman":"BUH-fuht","body":"a piece of furniture that stands at the side of a dining room; has shelves and drawers","clip":1},"wx-buffet":{"src":"concept:54:words:6:ex","route":"#/word/buffet","cta":"Open the word card","title":"In a sentence · buffet","body":"Winds buffeted the tent","clip":1},"wh-buffet":{"src":"concept:54:words:6:hook","route":"#/word/buffet","cta":"Open the word card","title":"Remember it · buffet","body":"A BUFFET has double F but only one T — you stuff yourself with food (FF) but stop at one T."},"wd-debut":{"src":"concept:54:words:7:def","route":"#/word/debut","cta":"Open the word card","title":"debut","roman":"day-BYOO","body":"the act of beginning something new","clip":1},"wx-debut":{"src":"concept:54:words:7:ex","route":"#/word/debut","cta":"Open the word card","title":"In a sentence · debut","body":"they looked forward to the debut of their new product line","clip":1},"wh-debut":{"src":"concept:54:words:7:hook","route":"#/word/debut","cta":"Open the word card","title":"Remember it · debut","body":"DEBUT is French — say 'day-BYOO' but spell it like the French, with no E at the end!"},"wd-corps":{"src":"concept:54:words:9:def","route":"#/word/corps","cta":"Open the word card","title":"corps","roman":"KAWR","body":"an army unit usually consisting of two or more divisions and their support","clip":1},"wx-corps":{"src":"concept:54:words:9:ex","route":"#/word/corps","cta":"Open the word card","title":"In a sentence · corps","body":"The Marine Corps trained intensively for months in the desert, preparing every soldier in the unit to work together as a disciplined team capable of handling the most challenging and dangerous missions.","clip":1},"wh-corps":{"src":"concept:54:words:9:hook","route":"#/word/corps","cta":"Open the word card","title":"Remember it · corps","body":"CORPS is spelled like corpse but you drop the E — the corps is alive, so it keeps its silent P-S but sheds the final E."},"wd-chassis":{"src":"concept:54:words:10:def","route":"#/word/chassis","cta":"Open the word card","title":"chassis","roman":"CHA-see","body":"the frame that a vehicle or machine is built on","clip":1},"wx-chassis":{"src":"concept:54:words:10:ex","route":"#/word/chassis","cta":"Open the word card","title":"In a sentence · chassis","body":"Our robotics team bolted the wheels and motor onto a light aluminium chassis.","clip":1},"wh-chassis":{"src":"concept:54:words:10:hook","route":"#/word/chassis","cta":"Open the word card","title":"Remember it · chassis","body":"The CHASSIS is the frame—it ends in '-is' like the skeleton it IS beneath the car."},"wd-faux":{"src":"concept:54:words:11:def","route":"#/word/faux","cta":"Open the word card","title":"faux","roman":"FAWKS","body":"not genuine or real; being an imitation of the genuine article","clip":1},"wx-faux":{"src":"concept:54:words:11:ex","route":"#/word/faux","cta":"Open the word card","title":"In a sentence · faux","body":"Her winter coat is lined with faux fur, so no animal was harmed.","clip":1},"wh-faux":{"src":"concept:54:words:11:hook","route":"#/word/faux","cta":"Open the word card","title":"Remember it · faux","body":"FAUX is French for fake — it looks genuine with four letters but sounds like just one syllable, FOE — faux is itself a little fake!"},"wx-debris":{"src":"concept:54:words:13:ex","route":"#/word/debris","cta":"Open the word card","title":"In a sentence · debris","body":"After the storm passed, volunteers spent the morning clearing debris from the streets and helping neighbors repair their fences.","clip":1},"wh-debris":{"src":"concept:54:words:13:hook","route":"#/word/debris","cta":"Open the word card","title":"Remember it · debris","body":"DEBRIS ends silently in S — the French left the S lying around like scattered rubble you can't hear."},"wo-debris":{"src":"lore:debris:0","route":"#/word/debris","cta":"Open the word card","title":"Where it comes from · debris","body":"French débris = broken down, from débriser = to break apart"},"wd-esprit":{"src":"concept:54:words:15:def","route":"#/word/esprit","cta":"Open the word card","title":"esprit","roman":"eh-SPREE","body":"liveliness of mind or spirit","clip":1},"wx-esprit":{"src":"concept:54:words:15:ex","route":"#/word/esprit","cta":"Open the word card","title":"In a sentence · esprit","body":"The drama club's performance was full of esprit, each actor delivering lines with sparkling energy and wit.","clip":1},"wh-esprit":{"src":"concept:54:words:15:hook","route":"#/word/esprit","cta":"Open the word card","title":"Remember it · esprit","body":"ESPRIT is the SPIRIT that leaps out of a lively mind — e-SPRIT."},"wx-nonchalant":{"src":"concept:54:words:16:ex","route":"#/word/nonchalant","cta":"Open the word card","title":"In a sentence · nonchalant","body":"Though the whole gym watched, Diego looked nonchalant as he sank the winning free throw.","clip":1},"wh-nonchalant":{"src":"concept:54:words:16:hook","route":"#/word/nonchalant","cta":"Open the word card","title":"Remember it · nonchalant","body":"A NON-CHALant person feels NO CHILL — they're too cool to care about anything."},"wo-nonchalant":{"src":"lore:nonchalant:0","route":"#/word/nonchalant","cta":"Open the word card","title":"Where it comes from · nonchalant","body":"French nonchaloir = to be unconcerned, from non- (not) + chaloir (to concern)"},"wd-coiffure":{"src":"concept:54:words:17:def","route":"#/word/coiffure","cta":"Open the word card","title":"coiffure","roman":"kwah-FYOOR","body":"the arrangement of the hair (especially a woman's hair)","clip":1},"wx-coiffure":{"src":"concept:54:words:17:ex","route":"#/word/coiffure","cta":"Open the word card","title":"In a sentence · coiffure","body":"Before the graduation ceremony, Isabella spent an hour perfecting her coiffure, weaving tiny flowers through her elegantly pinned-up curls.","clip":1},"wh-coiffure":{"src":"concept:54:words:17:hook","route":"#/word/coiffure","cta":"Open the word card","title":"Remember it · coiffure","body":"A COIFFURE is when you COIFf your hair into a fancy 'do—double the F, double the flair."},"wo-coiffure":{"src":"lore:coiffure:0","route":"#/word/coiffure","cta":"Open the word card","title":"Where it comes from · coiffure","body":"French coiffer = to dress hair, from coiffe = cap/headdress"},"li-u81":{"src":"concept:55:concept","route":"#/stop/u81","cta":"Open this stop","title":"French Agent Words: -eur / -eur","body":"French -eur = one who does (the French masculine agent suffix). These words never use -er — always -eur. And restaurateur never uses -n- before the -eur, despite what many people write."},"lc-u81-0":{"src":"concept:55:cards:0","route":"#/stop/u81","cta":"Open this stop","title":"French Agent Words: -eur / -eur · The -eur Agent","body":"In French, -eur = one who does (masculine form). Chauffeur = one who drives (chauffe = heat — early cars needed coal-heating!). Raconteur = one who tells stories. Connoisseur = one who knows. Saboteur = one who sabotages. Provocateur = one who provokes. Never -er for these words."},"lc-u81-1":{"src":"concept:55:cards:1","route":"#/stop/u81","cta":"Open this stop","title":"French Agent Words: -eur / -eur · The Restaurateur Trap","body":"Restaurateur (one who runs a restaurant) comes from restaurer (to restore). There is NO n before the -eur. Restauranteur is wrong — it inserts the n from the word \"restaurant\" which does not belong in the agent form. R-E-S-T-A-U-R-A-T-E-U-R. One of the most common misspellings in educated English."},"lc-u81-2":{"src":"concept:55:cards:2","route":"#/stop/u81","cta":"Open this stop","title":"French Agent Words: -eur / -eur · Entrepreneur Breakdown","body":"entre (between/undertake) + prendre (to take) + -eur = one who undertakes between supplier and customer. The word has several low-stress vowels: E-N-T-R-E-P-R-E-N-E-U-R. Spell by syllables: en · tre · pre · neur. Four syllables, twelve letters. No double letters anywhere."},"lc-u81-3":{"src":"concept:55:cards:3","route":"#/stop/u81","cta":"Open this stop","title":"French Agent Words: -eur / -eur · Grandeur — the Abstract -eur","body":"Grandeur = greatness, magnificence. Unlike the agent -eur words, grandeur comes from grand (great) + -eur (abstract quality suffix). Pronounced GRAN-jur. Note: -eur in this word = abstract quality, not a person. The same suffix serves two functions in French."},"lc-u81-4":{"src":"concept:55:cards:4","route":"#/stop/u81","cta":"Open this stop","title":"French Agent Words: -eur / -eur · More -eur Words","body":"Voyageur (voyager = to travel) = one who voyages/travels. Coiffeur (coiffer = to style hair) = one who styles hair. Masseur = one who gives massages (feminine: masseuse). Amateur (amat- = love) = one who does something for love rather than money — A-M-A-T-E-U-R, not amatuer."},"uq-u81-3":{"src":"unit:u81:qs:3","route":"#/stop/u81","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Remember the unusual 'eur' ending — the French ▁▁▁ ends like 'connoisseur'” — which word is this hook about?","opts":["entrepreneur","restaurateur","chauffeur","raconteur"],"after":"From “French Agent Words: -eur / -eur”."}},"wd-coiffeur":{"src":"concept:55:words:7:def","route":"#/word/coiffeur","cta":"Open the word card","title":"coiffeur","roman":"kwah-FUR","body":"a man hairdresser","clip":1},"wx-coiffeur":{"src":"concept:55:words:7:ex","route":"#/word/coiffeur","cta":"Open the word card","title":"In a sentence · coiffeur","body":"The celebrated Parisian coiffeur trimmed the actress's hair before her appearance on the red carpet.","clip":1},"wh-coiffeur":{"src":"concept:55:words:7:hook","route":"#/word/coiffeur","cta":"Open the word card","title":"Remember it · coiffeur","body":"A COIFFEUR has double 'f' and '-eur' — remember the French agent ending '-eur' like amateur or connoisseur."},"wd-masseur":{"src":"concept:55:words:8:def","route":"#/word/masseur","cta":"Open the word card","title":"masseur","roman":"ma-SUR","body":"a male massager","clip":1},"wx-masseur":{"src":"concept:55:words:8:ex","route":"#/word/masseur","cta":"Open the word card","title":"In a sentence · masseur","body":"The masseur at the spa worked out the knots in my shoulders after the long hike.","clip":1},"wh-masseur":{"src":"concept:55:words:8:hook","route":"#/word/masseur","cta":"Open the word card","title":"Remember it · masseur","body":"A massEUR ends in EUR like EURope — the French suffix reveals his continental training."},"wd-masseuse":{"src":"concept:55:words:9:def","route":"#/word/masseuse","cta":"Open the word card","title":"masseuse","roman":"mah-SUHZ","body":"a woman who gives massages professionally","clip":1},"wx-masseuse":{"src":"concept:55:words:9:ex","route":"#/word/masseuse","cta":"Open the word card","title":"In a sentence · masseuse","body":"After the marathon, the exhausted runner visited the masseuse, who expertly worked out the painful knots in her legs.","clip":1},"wh-masseuse":{"src":"concept:55:words:9:hook","route":"#/word/masseuse","cta":"Open the word card","title":"Remember it · masseuse","body":"massEUSE — the EUSE ending marks a French feminine profession"},"wd-grandeur":{"src":"concept:55:words:10:def","route":"#/word/grandeur","cta":"Open the word card","title":"grandeur","roman":"gra-NDOOR","body":"the quality of being magnificent or splendid or grand","clip":1},"wx-grandeur":{"src":"concept:55:words:10:ex","route":"#/word/grandeur","cta":"Open the word card","title":"In a sentence · grandeur","body":"Standing at the rim of the Grand Canyon, the students fell silent, overwhelmed by the sheer grandeur of the mile-deep chasm before them.","clip":1},"wh-grandeur":{"src":"concept:55:words:10:hook","route":"#/word/grandeur","cta":"Open the word card","title":"Remember it · grandeur","body":"Grand + eur = the quality of being grand"},"wd-amateur":{"src":"concept:55:words:12:def","route":"#/word/amateur","cta":"Open the word card","title":"amateur","roman":"A-muh-tur","body":"someone who pursues a study or sport as a pastime","clip":1},"wx-amateur":{"src":"concept:55:words:12:ex","route":"#/word/amateur","cta":"Open the word card","title":"In a sentence · amateur","body":"Although he was just an amateur photographer who had only owned his camera for a year, his stunning nature shots won first place at the regional art competition.","clip":1},"wh-amateur":{"src":"concept:55:words:12:hook","route":"#/word/amateur","cta":"Open the word card","title":"Remember it · amateur","body":"An amateur does it for LOVE — the word ends in -EUR (French for 'one who'), not -URE; think 'amat-EUR' loves it."},"wo-amateur":{"src":"lore:amateur:0","route":"#/word/amateur","cta":"Open the word card","title":"Where it comes from · amateur","body":"Latin amator = lover, from amare = to love"},"wd-auteur":{"src":"concept:55:words:13:def","route":"#/word/auteur","cta":"Open the word card","title":"auteur","roman":"oh-TUR","body":"a filmmaker who has a personal style and keeps creative control over his or her works","clip":1},"wx-auteur":{"src":"concept:55:words:13:ex","route":"#/word/auteur","cta":"Open the word card","title":"In a sentence · auteur","body":"Fans of the celebrated auteur lined up around the block hoping to catch a glimpse of the director whose unique style they could recognize in any frame.","clip":1},"wh-auteur":{"src":"concept:55:words:13:hook","route":"#/word/auteur","cta":"Open the word card","title":"Remember it · auteur","body":"AUTEUR sounds like AUTHOR: the filmmaker is the author of the film"},"wo-auteur":{"src":"lore:auteur:0","route":"#/word/auteur","cta":"Open the word card","title":"Where it comes from · auteur","body":"French auteur = author, from Latin auctor=originator"},"li-u82":{"src":"concept:56:concept","route":"#/stop/u82","cta":"Open this stop","title":"Italian Double Consonants: -zz / -cc / -ll / -pp","body":"Italian loves doubled consonants — they mark a short preceding vowel and are always preserved in English borrowings. Recognizing the double consonant = recognizing the Italian origin."},"lc-u82-0":{"src":"concept:56:cards:0","route":"#/stop/u82","cta":"Open this stop","title":"Italian Double Consonants: -zz / -cc / -ll / -pp · The Double Consonant Rule","body":"Italian uses doubled consonants to signal a short vowel before them — and English keeps these doublings intact. Mozzarella = M-O-Z-Z-A-R-E-L-L-A (double-z AND double-l). Intermezzo = I-N-T-E-R-M-E-Z-Z-O (double-z). Palazzo (palace) = P-A-L-A-Z-Z-O (double-z)."},"lc-u82-1":{"src":"concept:56:cards:1","route":"#/stop/u82","cta":"Open this stop","title":"Italian Double Consonants: -zz / -cc / -ll / -pp · -zz Words","body":"Mozzarella, intermezzo, palazzo, pizzicato (pizzicare = pinch), piazza (a square), paparazzi (paparazzo = a buzzing insect = a freelance photographer), mezzo (half). These zz words are among Italian's most recognizable exports to English."},"lc-u82-2":{"src":"concept:56:cards:2","route":"#/stop/u82","cta":"Open this stop","title":"Italian Double Consonants: -zz / -cc / -ll / -pp · -cc Words","body":"Cappuccino = C-A-P-P-U-C-C-I-N-O (double-p AND double-c). Broccoli = B-R-O-C-C-O-L-I (double-c). Bocce (lawn bowling) = B-O-C-C-E. Staccato (staccare = detach) = S-T-A-C-C-A-T-O (double-c). A cappella (a cappella = in the chapel style) = unaccompanied singing."},"lc-u82-3":{"src":"concept:56:cards:3","route":"#/stop/u82","cta":"Open this stop","title":"Italian Double Consonants: -zz / -cc / -ll / -pp · -ll/-pp Words","body":"Ballerina = B-A-L-L-E-R-I-N-A (double-l). Mozzarella has double-l too. Cappuccino has double-p. Soprano (NOT doubled — from sopra = above). Tempo (NOT doubled). The doubling signals a short stressed vowel — not all Italian words double."},"lc-u82-4":{"src":"concept:56:cards:4","route":"#/stop/u82","cta":"Open this stop","title":"Italian Double Consonants: -zz / -cc / -ll / -pp · Paparazzi — One Word, Two Doublings","body":"Paparazzi = P-A-P-A-R-A-Z-Z-I (double-z). The singular is paparazzo (P-A-P-A-R-A-Z-Z-O). This is a plural form in Italian — like alumni in Latin. Using \"paparazzi\" as a singular is technically wrong, though common in English. Bees may ask for the singular!"},"uq-u82-0":{"src":"unit:u82:qs:0","route":"#/stop/u82","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Italian Double Consonants: -zz / -cc / -ll / -pp”?","opts":["Italian loves doubled consonants — they mark a short preceding vowel and are always preserved in English borrowings.","In English words of Greek origin, y functions as a vowel, sounding like /i/ or /ee/.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil."],"after":"From “Italian Double Consonants: -zz / -cc / -ll / -pp”."}},"uq-u82-3":{"src":"unit:u82:qs:3","route":"#/stop/u82","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁has a DOUBLE Z like pizza has double cheese — mozZZarella!” — which word is this hook about?","opts":["mozzarella","intermezzo","palazzo","pizzicato"],"after":"From “Italian Double Consonants: -zz / -cc / -ll / -pp”."}},"wx-mozzarella":{"src":"concept:56:words:0:ex","route":"#/word/mozzarella","cta":"Open the word card","title":"In a sentence · mozzarella","body":"She stretched the warm mozzarella over the pizza dough before sliding it into the stone oven.","clip":1},"wh-mozzarella":{"src":"concept:56:words:0:hook","route":"#/word/mozzarella","cta":"Open the word card","title":"Remember it · mozzarella","body":"MOZZARELLAhas a DOUBLE Z like pizza has double cheese — mozZZarella!"},"wo-mozzarella":{"src":"lore:mozzarella:0","route":"#/word/mozzarella","cta":"Open the word card","title":"Where it comes from · mozzarella","body":"Italian mozzare = to cut off, referring to how the cheese is formed"},"wd-palazzo":{"src":"concept:56:words:2:def","route":"#/word/palazzo","cta":"Open the word card","title":"palazzo","roman":"puh-LAH-zoh","body":"A large, impressive Italian palace or mansion, especially one from the Renaissance period; also refers to wide-legged trousers resembling the flowing lines of such architecture.","clip":1},"wx-palazzo":{"src":"concept:56:words:2:ex","route":"#/word/palazzo","cta":"Open the word card","title":"In a sentence · palazzo","body":"The class visited a 15th-century palazzo in Florence whose marble corridors were lined with priceless Renaissance paintings.","clip":1},"wh-palazzo":{"src":"concept:56:words:2:hook","route":"#/word/palazzo","cta":"Open the word card","title":"Remember it · palazzo","body":"PALAZZO — a PALACE with a fancy Italian -zzo ending."},"wx-pizzicato":{"src":"concept:56:words:3:ex","route":"#/word/pizzicato","cta":"Open the word card","title":"In a sentence · pizzicato","body":"The violinists switched to pizzicato, plucking their strings to create a light, bouncy effect.","clip":1},"wh-pizzicato":{"src":"concept:56:words:3:hook","route":"#/word/pizzicato","cta":"Open the word card","title":"Remember it · pizzicato","body":"PIZZIcato has two Z's — pluck the strings TWICE, just like the double Z."},"wd-piazza":{"src":"concept:56:words:4:def","route":"#/word/piazza","cta":"Open the word card","title":"piazza","roman":"pee-A-zuh","body":"a public square with room for pedestrians","clip":1},"wx-piazza":{"src":"concept:56:words:4:ex","route":"#/word/piazza","cta":"Open the word card","title":"In a sentence · piazza","body":"Pigeons scattered across the sunny piazza while we ate ice cream beside the fountain.","clip":1},"wh-piazza":{"src":"concept:56:words:4:hook","route":"#/word/piazza","cta":"Open the word card","title":"Remember it · piazza","body":"Two z's keep the PIZZA of open Italian squares buzzing with life."},"wd-paparazzi":{"src":"concept:56:words:5:def","route":"#/word/paparazzi","cta":"Open the word card","title":"paparazzi","roman":"pah-pah-RAW-zee","body":"a freelance photographer who pursues celebrities trying to take candid photographs of them to sell to newspapers or magazines","clip":1},"wx-paparazzi":{"src":"concept:56:words:5:ex","route":"#/word/paparazzi","cta":"Open the word card","title":"In a sentence · paparazzi","body":"A swarm of paparazzi crowded outside the theater, cameras flashing as the movie star stepped out.","clip":1},"wh-paparazzi":{"src":"concept:56:words:5:hook","route":"#/word/paparazzi","cta":"Open the word card","title":"Remember it · paparazzi","body":"PAPARAZZI has a double Z — like two camera shutters clicking at once to catch celebrities."},"wd-cappuccino":{"src":"concept:56:words:6:def","route":"#/word/cappuccino","cta":"Open the word card","title":"cappuccino","roman":"ka-poo-CHEE-noh","body":"equal parts of espresso and hot milk topped with cinnamon and nutmeg and usually whipped cream","clip":1},"wx-cappuccino":{"src":"concept:56:words:6:ex","route":"#/word/cappuccino","cta":"Open the word card","title":"In a sentence · cappuccino","body":"She wrapped her hands around the warm mug and savored every sip of her morning cappuccino before heading to school.","clip":1},"wh-cappuccino":{"src":"concept:56:words:6:hook","route":"#/word/cappuccino","cta":"Open the word card","title":"Remember it · cappuccino","body":"cappUCCIno—double P, double C, like the two circular cups of espresso and milk a barista pours."},"wd-broccoli":{"src":"concept:56:words:7:def","route":"#/word/broccoli","cta":"Open the word card","title":"broccoli","roman":"BRAH-kuh-lee","body":"plant with dense clusters of tight green flower buds","clip":1},"wx-broccoli":{"src":"concept:56:words:7:ex","route":"#/word/broccoli","cta":"Open the word card","title":"In a sentence · broccoli","body":"The chef steamed fresh broccoli and tossed it with garlic butter to make a simple but delicious side dish.","clip":1},"wh-broccoli":{"src":"concept:56:words:7:hook","route":"#/word/broccoli","cta":"Open the word card","title":"Remember it · broccoli","body":"BROCCOLI has two C's like two little green CROWNS clustered together."},"wx-staccato":{"src":"concept:56:words:8:ex","route":"#/word/staccato","cta":"Open the word card","title":"In a sentence · staccato","body":"The young pianist's fingers danced across the keys in a rapid staccato style, producing short, crisp, detached notes that filled the concert hall with an exciting, percussive energy.","clip":1},"wh-staccato":{"src":"concept:56:words:8:hook","route":"#/word/staccato","cta":"Open the word card","title":"Remember it · staccato","body":"Staccato has double-c like two short detached notes — stac-CA-to, crisp and clipped."},"wd-ballerina":{"src":"concept:56:words:9:def","route":"#/word/ballerina","cta":"Open the word card","title":"ballerina","roman":"ba-ler-EE-nuh","body":"a female ballet dancer","clip":1},"wx-ballerina":{"src":"concept:56:words:9:ex","route":"#/word/ballerina","cta":"Open the word card","title":"In a sentence · ballerina","body":"The young ballerina practiced her pirouettes every day until she could spin without wobbling even once.","clip":1},"wh-ballerina":{"src":"concept:56:words:9:hook","route":"#/word/ballerina","cta":"Open the word card","title":"Remember it · ballerina","body":"A ballERINA has double L then -erina: think 'a ball-ER I kNow As' a dancer."},"wd-mezzo":{"src":"concept:56:words:10:def","route":"#/word/mezzo","cta":"Open the word card","title":"mezzo","roman":"MEH-zoh","body":"a soprano with a voice between soprano and contralto","clip":1},"wx-mezzo":{"src":"concept:56:words:10:ex","route":"#/word/mezzo","cta":"Open the word card","title":"In a sentence · mezzo","body":"The mezzo captivated the audience with her rich, warm voice that filled every corner of the concert hall.","clip":1},"wh-mezzo":{"src":"concept:56:words:10:hook","route":"#/word/mezzo","cta":"Open the word card","title":"Remember it · mezzo","body":"MEZZO has a double Z — her voice is right in the middle, strong as two Z's."},"wd-bocce":{"src":"concept:56:words:11:def","route":"#/word/bocce","cta":"Open the word card","title":"bocce","roman":"BOH-chee","body":"Italian bowling played on a long narrow dirt court","clip":1},"wx-bocce":{"src":"concept:56:words:11:ex","route":"#/word/bocce","cta":"Open the word card","title":"In a sentence · bocce","body":"Every Sunday afternoon, the neighbors gathered in the backyard to play a lively game of bocce.","clip":1},"wh-bocce":{"src":"concept:56:words:11:hook","route":"#/word/bocce","cta":"Open the word card","title":"Remember it · bocce","body":"BOCCE ends in -CE like 'ace' — roll the ball like an ace in this Italian game."},"wd-prosciutto":{"src":"concept:56:words:13:def","route":"#/word/prosciutto","cta":"Open the word card","title":"prosciutto","roman":"pruh-SHOO-toh","body":"Italian salt-cured ham usually sliced paper thin","clip":1},"wx-prosciutto":{"src":"concept:56:words:13:ex","route":"#/word/prosciutto","cta":"Open the word card","title":"In a sentence · prosciutto","body":"The chef draped thin slices of prosciutto over the ripe melon for a classic Italian appetizer.","clip":1},"wh-prosciutto":{"src":"concept:56:words:13:hook","route":"#/word/prosciutto","cta":"Open the word card","title":"Remember it · prosciutto","body":"Say it like 'pruh-SHOO-toh' — this Italian ham makes you shout SHOO as you chase people away from your plate; spell the silent C: proSCIutto."},"wd-bruschetta":{"src":"concept:56:words:14:def","route":"#/word/bruschetta","cta":"Open the word card","title":"bruschetta","roman":"broo-SKEH-tah","body":"toasted bread rubbed with garlic and topped with olive oil, tomatoes, and herbs","clip":1},"wx-bruschetta":{"src":"concept:56:words:14:ex","route":"#/word/bruschetta","cta":"Open the word card","title":"In a sentence · bruschetta","body":"At the Italian restaurant, we started with crispy bruschetta topped with fresh tomatoes and basil.","clip":1},"wh-bruschetta":{"src":"concept:56:words:14:hook","route":"#/word/bruschetta","cta":"Open the word card","title":"Remember it · bruschetta","body":"BRUSCHETTA has no SH — it's broo-SKET-ta; the SC makes a K sound, like a knife scraping toast."},"wd-risotto":{"src":"concept:56:words:15:def","route":"#/word/risotto","cta":"Open the word card","title":"risotto","roman":"ree-SAW-toh","body":"rice cooked with broth and sprinkled with grated cheese","clip":1},"wx-risotto":{"src":"concept:56:words:15:ex","route":"#/word/risotto","cta":"Open the word card","title":"In a sentence · risotto","body":"The chef stirred the creamy mushroom risotto slowly for twenty minutes until every grain of rice was perfectly tender.","clip":1},"wh-risotto":{"src":"concept:56:words:15:hook","route":"#/word/risotto","cta":"Open the word card","title":"Remember it · risotto","body":"RISOTTO has a double T — Two stirs to cook the rice just right."},"li-u83":{"src":"concept:57:concept","route":"#/stop/u83","cta":"Open this stop","title":"Italian Music & Art Vocabulary","body":"Italian is the language of classical music. Every dynamic marking, tempo marking, and musical technique has an Italian name. Spelling bees love these words for their unusual consonant patterns."},"lc-u83-0":{"src":"concept:57:cards:0","route":"#/stop/u83","cta":"Open this stop","title":"Italian Music & Art Vocabulary · Volume Dynamics — Softest to Loudest","body":"Pianissimo (pp) → piano (p, soft) → mezzo-piano (mp) → mezzo-forte (mf) → forte (f, loud) → fortissimo (ff). Piano = soft (NOT the instrument in this context!); forte = loud/strong; mezzo = half. Sforzando = suddenly very loud. Crescendo = gradually getting louder."},"lc-u83-1":{"src":"concept:57:cards:1","route":"#/stop/u83","cta":"Open this stop","title":"Italian Music & Art Vocabulary · Tempo Markings — Slowest to Fastest","body":"Grave (very slow, solemn) → largo (broad, slow) → adagio (slowly) → andante (walking pace) → moderato (moderate) → allegretto (fairly quick) → allegro (fast) → vivace (lively) → presto (very fast) → prestissimo (as fast as possible)."},"lc-u83-2":{"src":"concept:57:cards:2","route":"#/stop/u83","cta":"Open this stop","title":"Italian Music & Art Vocabulary · Technique Words","body":"Staccato (staccare = detach) = short, clipped notes. Legato (legare = tie/bind) = smoothly connected notes. Pizzicato (pizzicare = pinch) = plucking strings. Tremolo (tremare = tremble) = rapid repetition. Vibrato (vibrare = vibrate) = slight pitch variation."},"lc-u83-3":{"src":"concept:57:cards:3","route":"#/stop/u83","cta":"Open this stop","title":"Italian Music & Art Vocabulary · The -issimo Superlative","body":"Italian -issimo = most/very: pianissimo (very soft), fortissimo (very loud), prestissimo (very fast), bellissimo (very beautiful). This is a living Italian superlative still fully functional in music vocabulary. Note the double-s: P-I-A-N-I-S-S-I-M-O."},"lc-u83-4":{"src":"concept:57:cards:4","route":"#/stop/u83","cta":"Open this stop","title":"Italian Music & Art Vocabulary · Art Terms","body":"Chiaroscuro (chiaro = clear + oscuro = dark) = use of light and shadow in painting. Sfumato (sfumare = to evaporate) = Leonardo's technique of blurred outlines. Fresco (fresco = fresh) = painting on wet plaster. Impasto (impastare = to knead) = thick paint texture. Trompe-l'oeil (French!"},"uq-u83-3":{"src":"unit:u83:qs:3","route":"#/stop/u83","cta":"Open this stop","title":"Whose hook?","play":{"q":"“▁▁▁: FORCE it—▁▁▁ contains FORCE, which means play it HARD” — which word is this hook about?","opts":["sforzando","pianissimo","fortissimo","allegretto"],"after":"From “Italian Music & Art Vocabulary”."}},"wd-sforzando":{"src":"concept:57:words:0:def","route":"#/word/sforzando","cta":"Open the word card","title":"sforzando","roman":"sfort-SAHN-doh","body":"an accented chord","clip":1},"wx-sforzando":{"src":"concept:57:words:0:ex","route":"#/word/sforzando","cta":"Open the word card","title":"In a sentence · sforzando","body":"The pianist struck a sforzando on the final beat that made the audience jump in their seats.","clip":1},"wh-sforzando":{"src":"concept:57:words:0:hook","route":"#/word/sforzando","cta":"Open the word card","title":"Remember it · sforzando","body":"SFORZANDO: FORCE it—sforZANDO contains FORCE, which means play it HARD"},"wo-sforzando":{"src":"lore:sforzando:0","route":"#/word/sforzando","cta":"Open the word card","title":"Where it comes from · sforzando","body":"Italian sforzare = to force, from Latin ex- + fortis = strong"},"wx-fortissimo":{"src":"concept:57:words:2:ex","route":"#/word/fortissimo","cta":"Open the word card","title":"In a sentence · fortissimo","body":"The orchestra reached the fortissimo climax of the symphony, and the thunderous sound filled every corner of the concert hall.","clip":1},"wh-fortissimo":{"src":"concept:57:words:2:hook","route":"#/word/fortissimo","cta":"Open the word card","title":"Remember it · fortissimo","body":"FORTissimo — FORT-like STRENGTH of sound, double the 's' like double the volume"},"wo-fortissimo":{"src":"lore:fortissimo:0","route":"#/word/fortissimo","cta":"Open the word card","title":"Where it comes from · fortissimo","body":"Italian fortissimo = superlative of forte (loud), from Latin fortis = strong"},"wx-vivace":{"src":"concept:57:words:4:ex","route":"#/word/vivace","cta":"Open the word card","title":"In a sentence · vivace","body":"play this section vivace!","clip":1},"wh-vivace":{"src":"concept:57:words:4:hook","route":"#/word/vivace","cta":"Open the word card","title":"Remember it · vivace","body":"Vivace ends in 'ace' — play it fast and lively to ace your performance!"},"wx-prestissimo":{"src":"concept:57:words:5:ex","route":"#/word/prestissimo","cta":"Open the word card","title":"In a sentence · prestissimo","body":"this passage should be played prestissimo","clip":1},"wh-prestissimo":{"src":"concept:57:words:5:hook","route":"#/word/prestissimo","cta":"Open the word card","title":"Remember it · prestissimo","body":"PRESTO (fast) + ISSIMO (most) = PRESTISSIMO — the most-est presto you can possibly play."},"wx-legato":{"src":"concept:57:words:7:ex","route":"#/word/legato","cta":"Open the word card","title":"In a sentence · legato","body":"The cellist played the slow movement legato, drawing her bow smoothly across the strings so that each note flowed seamlessly into the next without the slightest interruption or gap.","clip":1},"wh-legato":{"src":"concept:57:words:7:hook","route":"#/word/legato","cta":"Open the word card","title":"Remember it · legato","body":"LEGATO means notes bound together smoothly — one G ties them gently, not two: l-e-G-a-t-o."},"wx-vibrato":{"src":"concept:57:words:10:ex","route":"#/word/vibrato","cta":"Open the word card","title":"In a sentence · vibrato","body":"The cellist added a rich vibrato to the long notes, making the melody sound warm and deeply emotional.","clip":1},"wh-vibrato":{"src":"concept:57:words:10:hook","route":"#/word/vibrato","cta":"Open the word card","title":"Remember it · vibrato","body":"VIBRATO ends in -ATO like a musical tomato—Italian music makes your voice shake and shimmer."},"wx-adagio":{"src":"concept:57:words:11:ex","route":"#/word/adagio","cta":"Open the word card","title":"In a sentence · adagio","body":"they played the adagio too quickly","clip":1},"wh-adagio":{"src":"concept:57:words:11:hook","route":"#/word/adagio","cta":"Open the word card","title":"Remember it · adagio","body":"Play it SLOWLY and at EASE — adagio has one G, as leisurely as the tempo itself."},"wx-moderato":{"src":"concept:57:words:12:ex","route":"#/word/moderato","cta":"Open the word card","title":"In a sentence · moderato","body":"The conductor instructed the orchestra to play the second movement moderato, keeping a steady and relaxed pace.","clip":1},"wh-moderato":{"src":"concept:57:words:12:hook","route":"#/word/moderato","cta":"Open the word card","title":"Remember it · moderato","body":"MODERATO is an Italian musical tempo—like a moderate TOMATO-red pace."},"wx-crescendo":{"src":"concept:57:words:14:ex","route":"#/word/crescendo","cta":"Open the word card","title":"In a sentence · crescendo","body":"The music crescendoes here","clip":1},"wh-crescendo":{"src":"concept:57:words:14:hook","route":"#/word/crescendo","cta":"Open the word card","title":"Remember it · crescendo","body":"A cresCENDO builds to CENTER stage — find the SCENE growing louder inside it."},"wo-chiaroscuro":{"src":"lore:chiaroscuro:0","route":"#/word/chiaroscuro","cta":"Open the word card","title":"Where it comes from · chiaroscuro","body":"Italian chiaro = light, clear (from Latin clarus) + oscuro = dark (from Latin obscurus)"},"wd-fresco":{"src":"concept:57:words:18:def","route":"#/word/fresco","cta":"Open the word card","title":"fresco","roman":"FREH-skoh","body":"a mural done with watercolors on wet plaster","clip":1},"wx-fresco":{"src":"concept:57:words:18:ex","route":"#/word/fresco","cta":"Open the word card","title":"In a sentence · fresco","body":"The art class studied the famous fresco painted on the ceiling of the Sistine Chapel by Michelangelo.","clip":1},"wh-fresco":{"src":"concept:57:words:18:hook","route":"#/word/fresco","cta":"Open the word card","title":"Remember it · fresco","body":"FRESCO is painted FRESH on wet plaster — FRES-CO starts with FRES like fresh."},"li-u84":{"src":"concept:94:concept","route":"#/stop/u84","cta":"Open this stop","title":"Arabic Loanwords","body":"Arabic gave English the al- prefix (Arabic \"the\") and a cluster of mathematics, astronomy, and science words. The al- is one of the most recognizable loanword signals in English."},"lc-u84-0":{"src":"concept:94:cards:0","route":"#/stop/u84","cta":"Open this stop","title":"Arabic Loanwords · The al- Signal (Arabic \"the\")","body":"Arabic al- = \"the\" was absorbed with the word into English. Algebra (al-jabr = reunion of broken parts). Algorithm (al-Khwarizmi = name of mathematician). Alchemy (al-kimiya = the transformation). Almanac (al-manakh = the calendar). Alcove (al-qubba = the vault)."},"lc-u84-1":{"src":"concept:94:cards:1","route":"#/stop/u84","cta":"Open this stop","title":"Arabic Loanwords · Mathematics from Arabic","body":"Algebra, algorithm, cipher (sifr = zero), zero (sifr through Italian zefiro). Arabs preserved and advanced Greek mathematics when Europe had lost it. When Europe rediscovered math through Arabic texts in the 12th century, it absorbed Arabic mathematical vocabulary wholesale."},"lc-u84-2":{"src":"concept:94:cards:2","route":"#/stop/u84","cta":"Open this stop","title":"Arabic Loanwords · Astronomy from Arabic","body":"Zenith (samt = direction overhead). Nadir (nazir = opposite). Azimuth (al-samt) = a compass bearing. Aldebaran, Algol, Altair, Betelgeuse — many star names begin with Al- (= \"the star of...\"). Arabic astronomers named the stars and the names stuck."},"lc-u84-3":{"src":"concept:94:cards:3","route":"#/stop/u84","cta":"Open this stop","title":"Arabic Loanwords · Chemistry & Trade from Arabic","body":"Elixir (al-iksir = the philosopher's stone). Tariff (ta'rifa = notification of price). Hazard (az-zahr = the dice). Magazine (makhazin = storehouses). Safari (safara = to travel). Assassin (hashishin = hashish users = a medieval sect). Etymology reveals medieval history."},"lc-u84-4":{"src":"concept:94:cards:4","route":"#/stop/u84","cta":"Open this stop","title":"Arabic Loanwords · Spelling Arabic Loanwords","body":"The al- prefix may appear as al-, el-, or absorbed: algebra, alchemy, alcohol (al + kohl). Some lost the al-: chemistry (from alchemy), cotton (Arabic qutn)."},"uq-u84-0":{"src":"unit:u84:qs:0","route":"#/stop/u84","cta":"Open this stop","title":"The big idea","play":{"q":"Which of these is the big idea of “Arabic Loanwords”?","opts":["Arabic gave English the al- prefix (Arabic \"the\") and a cluster of mathematics, astronomy, and science words.","In English words of Greek origin, y functions as a vowel, sounding like /i/ or /ee/.","Latin dis- = apart, not, or deprived of.","Latin malus = bad, evil."],"after":"From “Arabic Loanwords”."}},"uq-u84-3":{"src":"unit:u84:qs:3","route":"#/stop/u84","cta":"Open this stop","title":"Whose hook?","play":{"q":"“AL-GE-BRA: ▁▁▁ reunites broken numbers — spell it straight: a-l-g-e-b-r-a, no extra 'e'.” — which word is this hook about?","opts":["algebra","algorithm","alchemy","almanac"],"after":"From “Arabic Loanwords”."}},"wd-algebra":{"src":"concept:94:words:0:def","route":"#/word/algebra","cta":"Open the word card","title":"algebra","roman":"A-ljuh-bruh","body":"the mathematics of generalized arithmetical operations","clip":1},"wx-algebra":{"src":"concept:94:words:0:ex","route":"#/word/algebra","cta":"Open the word card","title":"In a sentence · algebra","body":"Once she understood how to solve for x, algebra suddenly seemed far less frightening than it had before.","clip":1},"wh-algebra":{"src":"concept:94:words:0:hook","route":"#/word/algebra","cta":"Open the word card","title":"Remember it · algebra","body":"AL-GE-BRA: algebra reunites broken numbers — spell it straight: a-l-g-e-b-r-a, no extra 'e'."},"wd-alchemy":{"src":"concept:94:words:2:def","route":"#/word/alchemy","cta":"Open the word card","title":"alchemy","roman":"A-lkuh-mee","body":"an early form of chemistry whose followers tried to turn ordinary metals into gold","clip":1},"wx-alchemy":{"src":"concept:94:words:2:ex","route":"#/word/alchemy","cta":"Open the word card","title":"In a sentence · alchemy","body":"Medieval students of alchemy mixed powders for years, hoping to turn lead into gold.","clip":1},"wh-alchemy":{"src":"concept:94:words:2:hook","route":"#/word/alchemy","cta":"Open the word card","title":"Remember it · alchemy","body":"ALCHemy has an ITCH in the middle — transforming metals is an itchy business."},"wd-almanac":{"src":"concept:94:words:3:def","route":"#/word/almanac","cta":"Open the word card","title":"almanac","roman":"AH-lmuh-nak","body":"an annual publication including weather forecasts and other miscellaneous information arranged according to the calendar of a given year","clip":1},"wx-almanac":{"src":"concept:94:words:3:ex","route":"#/word/almanac","cta":"Open the word card","title":"In a sentence · almanac","body":"Farmer Greta checked the almanac every January to plan which crops to plant each month.","clip":1},"wh-almanac":{"src":"concept:94:words:3:hook","route":"#/word/almanac","cta":"Open the word card","title":"Remember it · almanac","body":"AL-MA-NAC: 'ALL MAN needs A Calendar' — an almanac tells everyone the dates."},"wo-almanac":{"src":"lore:almanac:0","route":"#/word/almanac","cta":"Open the word card","title":"Where it comes from · almanac","body":"Arabic al-manakh = the calendar/climate"},"wd-alcove":{"src":"concept:94:words:4:def","route":"#/word/alcove","cta":"Open the word card","title":"alcove","roman":"A-lkohv","body":"a small recess opening off a larger room","clip":1},"wx-alcove":{"src":"concept:94:words:4:ex","route":"#/word/alcove","cta":"Open the word card","title":"In a sentence · alcove","body":"She curled up in the cozy alcove with a book while the storm raged outside.","clip":1},"wh-alcove":{"src":"concept:94:words:4:hook","route":"#/word/alcove","cta":"Open the word card","title":"Remember it · alcove","body":"An ALCOVe is like a COVE tucked inside a room — end it with a silent E like a cave."},"wd-zenith":{"src":"concept:94:words:5:def","route":"#/word/zenith","cta":"Open the word card","title":"zenith","roman":"ZEE-nuhth","body":"the point above the observer that is directly opposite the nadir on the imaginary sphere against which celestial bodies appear to be projected","clip":1},"wx-zenith":{"src":"concept:94:words:5:ex","route":"#/word/zenith","cta":"Open the word card","title":"In a sentence · zenith","body":"At noon in midsummer, the blazing sun hung near its zenith, casting almost no shadow on the ground below.","clip":1},"wh-zenith":{"src":"concept:94:words:5:hook","route":"#/word/zenith","cta":"Open the word card","title":"Remember it · zenith","body":"At the ZENITH, the sun shines on your ZEN forehead — Z-E-N-I-T-H, straight overhead."},"wd-nadir":{"src":"concept:94:words:6:def","route":"#/word/nadir","cta":"Open the word card","title":"nadir","roman":"NAY-der","body":"an extreme state of adversity; the lowest point of anything","clip":1},"wx-nadir":{"src":"concept:94:words:6:ex","route":"#/word/nadir","cta":"Open the word card","title":"In a sentence · nadir","body":"Failing the championship match felt like the nadir of his athletic career, but he vowed to come back stronger.","clip":1},"wh-nadir":{"src":"concept:94:words:6:hook","route":"#/word/nadir","cta":"Open the word card","title":"Remember it · nadir","body":"NADIR — the lowest point; NADiR, think 'NADir Is Rock-bottom,' ends in -ir not -ier."},"wx-azimuth":{"src":"concept:94:words:7:ex","route":"#/word/azimuth","cta":"Open the word card","title":"In a sentence · azimuth","body":"The navigator carefully calculated the azimuth to ensure the ship was heading in the correct direction across the open sea.","clip":1},"wh-azimuth":{"src":"concept:94:words:7:hook","route":"#/word/azimuth","cta":"Open the word card","title":"Remember it · azimuth","body":"AZIMUTH ends in -UTH like 'truth' — the TRUE horizontal angle to your target."},"wo-azimuth":{"src":"lore:azimuth:0","route":"#/word/azimuth","cta":"Open the word card","title":"Where it comes from · azimuth","body":"Arabic al-sumūt = the directions/paths (plural of al-samt)"},"wd-elixir":{"src":"concept:94:words:8:def","route":"#/word/elixir","cta":"Open the word card","title":"elixir","roman":"ih-LIH-kser","body":"a sweet flavored liquid (usually containing a small amount of alcohol) used in compounding medicines to be taken by mouth in order to mask an unpleasant taste","clip":1},"wx-elixir":{"src":"concept:94:words:8:ex","route":"#/word/elixir","cta":"Open the word card","title":"In a sentence · elixir","body":"The old herbalist claimed his elixir could cure a cold in just one day.","clip":1},"wh-elixir":{"src":"concept:94:words:8:hook","route":"#/word/elixir","cta":"Open the word card","title":"Remember it · elixir","body":"An ELIXIR ends in '-ir' not '-er' — remember: it's a magic liquid, and magic words end in '-ir' like 'flair'."},"wx-tariff":{"src":"concept:94:words:9:ex","route":"#/word/tariff","cta":"Open the word card","title":"In a sentence · tariff","body":"Because of a new tariff on imported cocoa, chocolate bars cost more this year.","clip":1},"wh-tariff":{"src":"concept:94:words:9:hook","route":"#/word/tariff","cta":"Open the word card","title":"Remember it · tariff","body":"A tarIFF has one R and double F—the government takes a FiFth with two F's."},"wo-tariff":{"src":"lore:tariff:0","route":"#/word/tariff","cta":"Open the word card","title":"Where it comes from · tariff","body":"Arabic ta'rif = notification, schedule of fees"},"wd-hazard":{"src":"concept:94:words:10:def","route":"#/word/hazard","cta":"Open the word card","title":"hazard","roman":"HA-zerd","body":"a source of danger; a possibility of incurring loss or misfortune","clip":1},"wx-hazard":{"src":"concept:94:words:10:ex","route":"#/word/hazard","cta":"Open the word card","title":"In a sentence · hazard","body":"drinking alcohol is a health hazard","clip":1},"wh-hazard":{"src":"concept:94:words:10:hook","route":"#/word/hazard","cta":"Open the word card","title":"Remember it · hazard","body":"A HAZard is a DANGER—there's only one Z in hazard, just as one bad roll of the dice is enough."},"wd-safari":{"src":"concept:94:words:12:def","route":"#/word/safari","cta":"Open the word card","title":"safari","roman":"suh-FAH-ree","body":"an overland journey by hunters (especially in Africa)","clip":1},"wx-safari":{"src":"concept:94:words:12:ex","route":"#/word/safari","cta":"Open the word card","title":"In a sentence · safari","body":"On their African safari, the family spotted a pride of lions resting under an acacia tree.","clip":1},"wh-safari":{"src":"concept:94:words:12:hook","route":"#/word/safari","cta":"Open the word card","title":"Remember it · safari","body":"On SAFARI you travel FAR — the word 'FAR' hides inside sAFARi, reminding you it's one 'f', not two."},"wx-assassin":{"src":"concept:94:words:13:ex","route":"#/word/assassin","cta":"Open the word card","title":"In a sentence · assassin","body":"his assassins were hunted down like animals","clip":1},"wh-assassin":{"src":"concept:94:words:13:hook","route":"#/word/assassin","cta":"Open the word card","title":"Remember it · assassin","body":"ASSASSIN has two double-S pairs — remember: ASS-ASS-IN, with two 'donkeys' charging in!"},"wo-assassin":{"src":"lore:assassin:0","route":"#/word/assassin","cta":"Open the word card","title":"Where it comes from · assassin","body":"Arabic hashshashin = hashish users; a medieval sect known for political murders"},"wx-alcohol":{"src":"concept:94:words:14:ex","route":"#/word/alcohol","cta":"Open the word card","title":"In a sentence · alcohol","body":"alcohol (or drink) ruined him","clip":1},"wh-alcohol":{"src":"concept:94:words:14:hook","route":"#/word/alcohol","cta":"Open the word card","title":"Remember it · alcohol","body":"ALCOHOL: remember AL always COHabits with OL — al-co-hol."},"wd-cipher":{"src":"concept:94:words:15:def","route":"#/word/cipher","cta":"Open the word card","title":"cipher","roman":"SEYE-fer","body":"a message written in a secret code","clip":1},"wx-cipher":{"src":"concept:94:words:15:ex","route":"#/word/cipher","cta":"Open the word card","title":"In a sentence · cipher","body":"Grandad's diary was written in a cipher that took me three afternoons to crack.","clip":1},"wh-cipher":{"src":"concept:94:words:15:hook","route":"#/word/cipher","cta":"Open the word card","title":"Remember it · cipher","body":"CIPHER starts with 'ci' not 'cy' — the secret code hides an 'i,' not a 'y'."},"li-u85":{"src":"concept:95:concept","route":"#/stop/u85","cta":"Open this stop","title":"Spanish Loanwords","body":"Spanish gave English its American landscape vocabulary, animal names, and food words. The signature patterns: -illo/-illa diminutives, ll = /y/ sound, and j = /h/ sound."},"lc-u85-0":{"src":"concept:95:cards:0","route":"#/stop/u85","cta":"Open this stop","title":"Spanish Loanwords · The -illo/-illa Diminutive","body":"Spanish -illo/-illa = small version (diminutive). Armadillo (armado = armored + -illo = small armored one). Guerrilla (guerra = war + -illa = small war = irregular warfare). Vanilla (vaina = pod + -illa = small pod). Peccadillo (pecado = sin + -illo = small sin = a minor fault)."},"lc-u85-1":{"src":"concept:95:cards:1","route":"#/stop/u85","cta":"Open this stop","title":"Spanish Loanwords · American Landscape & Animals","body":"Canyon (from cañón = large tube). Armadillo = the armored animal. Alligator (from el lagarto = the lizard). Mosquito (mosca = fly + -ito = small fly). Cockroach (cucaracha). Tornado (tornada = thunderstorm). Hacienda = a large estate. Sierra = a jagged mountain range. Rodeo = rodear = to go around."},"lc-u85-2":{"src":"concept:95:cards:2","route":"#/stop/u85","cta":"Open this stop","title":"Spanish Loanwords · Food from Spanish","body":"Chocolate (from Nahuatl xocolatl through Spanish). Tomato (from Nahuatl tomatl). Avocado (from Nahuatl ahuacatl). Chili (chilli in Nahuatl). Tortilla (torta = cake + -illa = small cake). These passed through Spanish from indigenous American languages — double linguistic heritage."},"lc-u85-3":{"src":"concept:95:cards:3","route":"#/stop/u85","cta":"Open this stop","title":"Spanish Loanwords · ll = /y/ and Other Sounds","body":"In Spanish, ll = /y/ sound: tortilla = /tor-TEE-yuh/. Guerrilla = /guh-RIL-uh/ (in English, the double-l sounds as /l/). The j = /h/ in Spanish: jalapeño = /hah-luh-PAY-nyoh/. Junta = /HUN-tuh or /JUN-tuh in English. These original Spanish sounds change as words enter English."},"lc-u85-4":{"src":"concept:95:cards:4","route":"#/stop/u85","cta":"Open this stop","title":"Spanish Loanwords · Spelling Spanish Loanwords","body":"Guerrilla = G-U-E-R-R-I-L-L-A (double-r AND double-l). Armadillo = A-R-M-A-D-I-L-L-O (double-l). Sarsaparilla = S-A-R-S-A-P-A-R-I-L-L-A (double-l). Mosquito = M-O-S-Q-U-I-T-O (qu = /k/ before i). Vanilla = V-A-N-I-L-L-A (double-l)."},"uq-u85-3":{"src":"unit:u85:qs:3","route":"#/stop/u85","cta":"Open this stop","title":"Whose hook?","play":{"q":"“Two r's and two l's—▁▁▁ warfare is doubly intense” — which word is this hook about?","opts":["guerrilla","armadillo","vanilla","peccadillo"],"after":"From “Spanish Loanwords”."}},"wd-guerrilla":{"src":"concept:95:words:0:def","route":"#/word/guerrilla","cta":"Open the word card","title":"guerrilla","roman":"ger-IH-luh","body":"a member of an irregular armed force that fights a stronger force by sabotage and harassment","clip":1},"wx-guerrilla":{"src":"concept:95:words:0:ex","route":"#/word/guerrilla","cta":"Open the word card","title":"In a sentence · guerrilla","body":"The guerrilla fighters used their knowledge of the jungle terrain to launch surprise raids and then vanish before the larger army could respond.","clip":1},"wh-guerrilla":{"src":"concept:95:words:0:hook","route":"#/word/guerrilla","cta":"Open the word card","title":"Remember it · guerrilla","body":"Two r's and two l's—guerrilla warfare is doubly intense"},"wo-guerrilla":{"src":"lore:guerrilla:0","route":"#/word/guerrilla","cta":"Open the word card","title":"Where it comes from · guerrilla","body":"Spanish guerra = war + diminutive -illa (little war)"},"wd-armadillo":{"src":"concept:95:words:1:def","route":"#/word/armadillo","cta":"Open the word card","title":"armadillo","roman":"ah-rmuh-DIH-loh","body":"burrowing chiefly nocturnal mammal with body covered with strong horny plates","clip":1},"wx-armadillo":{"src":"concept:95:words:1:ex","route":"#/word/armadillo","cta":"Open the word card","title":"In a sentence · armadillo","body":"The armadillo curled into a tight ball when it sensed danger, relying on its tough armored shell for protection.","clip":1},"wh-armadillo":{"src":"concept:95:words:1:hook","route":"#/word/armadillo","cta":"Open the word card","title":"Remember it · armadillo","body":"armaDILLo — the armored animal that DRILLS into dirt"},"wo-armadillo":{"src":"lore:armadillo:0","route":"#/word/armadillo","cta":"Open the word card","title":"Where it comes from · armadillo","body":"Spanish 'armado' = armed + diminutive '-illo' = little — meaning 'little armored one'"},"wx-vanilla":{"src":"concept:95:words:2:ex","route":"#/word/vanilla","cta":"Open the word card","title":"In a sentence · vanilla","body":"he liked vanilla ice cream","clip":1},"wh-vanilla":{"src":"concept:95:words:2:hook","route":"#/word/vanilla","cta":"Open the word card","title":"Remember it · vanilla","body":"VaNILLa has two L's, just like the TALL vanilla bean pods standing side by side."},"wo-vanilla":{"src":"lore:vanilla:0","route":"#/word/vanilla","cta":"Open the word card","title":"Where it comes from · vanilla","body":"Spanish vainilla = little pod/sheath"},"wx-peccadillo":{"src":"concept:95:words:3:ex","route":"#/word/peccadillo","cta":"Open the word card","title":"In a sentence · peccadillo","body":"Forgetting to return a library book on time is a peccadillo, not a crime worth losing sleep over.","clip":1},"wh-peccadillo":{"src":"concept:95:words:3:hook","route":"#/word/peccadillo","cta":"Open the word card","title":"Remember it · peccadillo","body":"A PECCADILLO is a little sin — it ends in DILLO like an armaDILLO, a small creature just like a small offense."},"wo-peccadillo":{"src":"lore:peccadillo:0","route":"#/word/peccadillo","cta":"Open the word card","title":"Where it comes from · peccadillo","body":"Spanish pecadillo, diminutive of pecado = sin, from Latin peccare"},"wx-sarsaparilla":{"src":"concept:95:words:4:ex","route":"#/word/sarsaparilla","cta":"Open the word card","title":"In a sentence · sarsaparilla","body":"The old-fashioned soda shop served a frothy glass of sarsaparilla that tasted like something from another era.","clip":1}});
